// content.js — static reference data for the CCA-F Study Suite.
// Extracted verbatim from index.html; loaded via <script src> in <head>.
// Read-only at runtime: nothing in the app mutates these.
// Per Constitution Principle IV, edit these literals with a script, not by hand.
"use strict";
const QDATA=[
{"id": "ts-1.1-01", "q": "Your pipeline reviews every PR using a single API call with a static prompt containing the diff and full text of each changed file — unchanged files are not included. Reviews are posted asynchronously and don't block PR creation. Developers report that reviews consistently miss bugs involving cross-file interactions — for example, a PR renames a function's parameters but the review doesn't flag callers in unchanged files that still use the old argument order. Evaluation shows cross-file bugs account for 35% of production incidents from reviewed PRs. What is the most effective change to your review design?", "o": {"A": "Redesign the review as a turn-limited agentic task where the model can read files and search the codebase via tools, following references to verify cross-file findings.", "B": "Add chain-of-thought instructions asking the model to list all external references in the diff, then reason step-by-step about how each change might affect callers in other files.", "C": "Run parallel review passes per changed file with direct dependents included in each pass, then aggregate and deduplicate findings using a final summarization call.", "D": "Use static analysis to build a dependency graph of changed code, then expand the prompt to include all files within two dependency hops of any changed file."}, "a": "A", "w": "The failure is a missing-context problem: callers live in unchanged files the static prompt never includes, so chain-of-thought (B) cannot help the model reason about code it cannot see, and static heuristics (C, D) bloat context while still missing dynamic or multi-hop references. Anthropic's agent guidance favors agentic search — letting the model retrieve exactly the context it needs via file-read/search tools — and the asynchronous, nonblocking review pipeline tolerates the added latency, while a turn limit bounds cost.", "c": "Prompting Techniques", "dup": "", "conflict": false, "ts": "ts-1.1"},
{"id": "ts-1.6-01", "q": "An engineer asks your agent to add comprehensive tests to a legacy codebase with 200 files and minimal existing test coverage. The engineer hasn't specified which modules to prioritize. How should the agent decompose this open-ended task?", "o": {"A": "Systematically read all 200 files to create a complete function inventory before writing any tests, ensuring the testing plan accounts for every function before beginning.", "B": "Create a fixed testing schedule upfront based on directory structure, allocating equal effort to each top-level directory regardless of code complexity or business importance.", "C": "Start writing tests for the first module alphabetically, using test failures and imports to discover related files organically.", "D": "Use Glob and Grep to map codebase structure, identify heavily-coupled modules, create a prioritized plan for high-impact areas, and revise as dependencies are discovered."}, "a": "D", "w": "Anthropic's agent best practices favor efficient context gathering with search tools (Glob/Grep) over exhaustively reading every file, which would waste context and time. Prioritizing high-impact, heavily-coupled modules and iteratively revising the plan as dependencies surface is the correct way to decompose an open-ended task; A is wasteful, B ignores impact/complexity, and C is arbitrary and unplanned.", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-1.6"},
{"id": "ts-1.6-02", "q": "An engineer submits two requests: • Request A: \"Rename the getUserData function to fetchUserProfile everywhere it's used.\" • Request B: \"Improve error handling throughout the data processing module—add try/catch blocks, meaningful error messages, and ensure failures don't silently corrupt data.\" For which request does specifying an explicit multi-phase workflow (such as analyze propose implement with review) most improve outcome quality?", "o": {"A": "Request B, the error handling task", "B": "Both requests benefit equally", "C": "Request A, the function rename task", "D": "Neither request benefits significantly"}, "a": "A", "w": "Request B is open-ended and judgment-heavy — \"improve error handling\" requires analyzing current behavior, deciding where try/catch belongs, and choosing meaningful messages, so an explicit analyze propose implement-with-review workflow materially raises quality and catches bad design before code changes. Request A is a mechanical, well-defined rename that a simple find-and-replace-style execution handles fine, so the multi-phase structure adds little.", "c": "Agent vs. Workflow Design", "dup": "", "conflict": false, "ts": "ts-1.6"},
{"id": "ts-1.4-01", "q": "Your code review assistant needs to analyze pull requests and provide feedback on three aspects: code style compliance, potential security issues, and documentation completeness. Each aspect requires reading files, running analysis tools, and generating a report section. The review process follows the same three-step workflow for every PR. Which task decomposition pattern is most appropriate for this workflow?", "o": {"A": "Single comprehensive prompt—include all instructions in one prompt and let the model handle all three aspects simultaneously.", "B": "Routing—classify each PR by type (feature, bugfix, refactor) first, then route to different review prompts optimized for that category.", "C": "Prompt chaining—break the review into sequential steps where each aspect (style, security, documentation) is analyzed separately, with outputs combined in a final synthesis step.", "D": "Orchestrator-workers—have a central LLM analyze each PR to dynamically determine which checks are needed, then delegate to specialized worker LLMs for each identified subtask."}, "a": "C", "w": "The scenario explicitly states the review \"follows the same three-step workflow for every PR,\" which per Anthropic's \"Building Effective Agents\" guidance is the textbook case for the prompt chaining workflow: a fixed, predictable sequence of subtasks each handled by a focused prompt, then synthesized. Orchestrator-workers (D) is only warranted when the needed subtasks vary unpredictably per input, and routing (B) applies when inputs fall into distinct categories needing different handling—neither fits a fixed, identical workflow.", "c": "Workflow Patterns", "dup": "", "conflict": false, "ts": "ts-1.4"},
{"id": "ts-1.7-01", "q": "Your multi-agent research pipeline crashed after processing 12 of 28 documents. The web search agent had identified relevant sources, the document analyzer had partially completed extraction, and the synthesizer had begun pattern identification. You need to resume processing without repeating work or losing fidelity of prior findings. What state management approach best balances information fidelity with context efficiency when restoring agent state?", "o": {"A": "Have each agent maintain its own persistent state file and reload it independently at the start of each session.", "B": "Persist the coordinator's conversation log containing all task delegations and responses, providing this to agents when resuming.", "C": "Index all agent outputs in a shared vector store. When resuming, each agent queries the store using semantic search to retrieve relevant prior findings.", "D": "Have each agent persist a structured export to a known location. On resume, the coordinator loads the manifest and injects relevant state into agent prompts."}, "a": "D", "w": "Anthropic's multi-agent best practices recommend persisting structured artifacts to external storage and having the orchestrator selectively re-inject only the relevant state into each subagent's context. This preserves fidelity (lossless structured exports plus a manifest of completed work) while staying context-efficient, whereas A lacks coordinated resume logic, B floods agents with an entire conversation log, and C's semantic search is lossy and may miss or garble prior findings.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.7"},
{"id": "ts-1.3-01", "q": "Analysis reveals the coordinator invokes the web search subagent, waits for its response, then invokes the document analysis subagent and waits again. These tasks are independent—neither requires the other's output. How should you modify the system to run these subagents concurrently?", "o": {"A": "Switch both subagents to use a Haiku-tier model instead of Sonnet to reduce their individual execution time.", "B": "Create an async orchestration layer outside the agent that spawns parallel threads, each running a separate coordinator-subagent pair, then aggregates results.", "C": "Structure the coordinator to emit both Task tool calls (for web search and document analysis) in a single response message rather than across separate conversation turns.", "D": "Add detailed instructions to the coordinator's system prompt explaining the performance benefits of parallel execution and requesting it invoke both subagents at the same time."}, "a": "C", "w": "In Claude's agent architecture, subagents run concurrently when the coordinator emits multiple Task tool calls in a single assistant message — the harness executes parallel tool_use blocks from the same turn simultaneously. Option A only speeds up each serial step, B adds unnecessary external infrastructure duplicating what the agent loop already supports, and D merely explains/requests parallelism without ensuring the structural mechanism (same-message tool calls) that actually produces concurrent execution.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.3"},
{"id": "ts-1.3-02", "q": "The coordinator agent has AgentDefinitions configured for all four specialized subagents, each with appropriate descriptions, prompts, and tool restrictions. During testing, you notice the coordinator correctly reasons about when to delegate—it generates messages like \"I'll ask the web search agent to find sources on this topic\"—but no subagent execution ever occurs. The coordinator then proceeds as if the delegation happened and continues with incomplete information. Logs show no errors. What is the most likely cause?", "o": {"A": "The AgentDefinitions are configured correctly, but the coordinator's system prompt doesn't explicitly list the available subagent types, preventing the model from knowing they can be invoked.", "B": "Subagent context isolation means task descriptions from the coordinator don't automatically reach subagents; you need to configure explicit context forwarding in ClaudeAgentOptions.", "C": "The coordinator's max_tokens setting is too low, causing the Task tool invocation to be truncated before the subagent type parameter can be specified.", "D": "The coordinator's allowedTools configuration doesn't include \"Task\", so while it can reason about delegation, it cannot invoke the tool required to spawn subagents."}, "a": "D", "w": "In the Claude Agent SDK, subagents defined via AgentDefinitions are launched through the Task tool; if allowedTools omits \"Task\", the coordinator can still verbally reason about delegating but has no mechanism to actually spawn subagents, and it silently continues without them—matching the symptom of no execution and no errors. Truncated max_tokens (C) or missing prompt listings (A) would produce errors or different behavior, and context isolation (B) doesn't prevent invocation.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.3"},
{"id": "ts-1.2-01", "q": "A landmark case citing 12 precedents takes over 3 minutes to analyze completely. What's the most effective way to reduce this latency while preserving the coordinator's ability to monitor and debug the system?", "o": {"A": "Have the coordinator spawn parallel document analysis subagents, each handling a subset of precedents, then aggregate results before synthesis", "B": "Enable the document analysis subagent to spawn its own specialized subagents dynamically when it encounters cases with many citations", "C": "Create a recursive agent hierarchy where analysis agents subdivide work among child agents until reaching single-precedent granularity", "D": "Implement a message queue where precedent analysis tasks are processed asynchronously by a pool of worker agents"}, "a": "A", "w": "Anthropic's recommended multi-agent design is the orchestrator-worker pattern with a flat hierarchy: the coordinator itself spawns parallel subagents and aggregates their results, which cuts latency through parallelism while keeping all spawning, monitoring, and debugging centralized in one place. Options B and C create nested/recursive agent hierarchies that severely degrade observability and debuggability, and D introduces asynchronous queue infrastructure that decouples work from the coordinator's direct visibility.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.2"},
{"id": "ts-5.6-01", "q": "In production, final reports frequently contain claims without proper source attribution. Investigation shows that while the web search and document analysis agents correctly attach citations to their outputs, the synthesis agent loses track of which sources support which conclusions when combining findings. What's the most effective architectural change?", "o": {"A": "Have the coordinator inject source identifier prefixes into text before each handoff, then parse these prefixes at report generation to reconstruct citations.", "B": "Maintain complete transcripts of all subagent interactions and add a citation-resolution agent to analyze logs and determine attributions before report generation.", "C": "Require all subagents to output structured claim-source mappings that the synthesis agent must preserve and merge when combining findings from multiple sources.", "D": "Add a verification step where the report generator uses semantic similarity matching against original sources to reconstruct which claims came from which documents."}, "a": "C", "w": "The failure is information loss at the synthesis stage, so the fix is to carry attribution as structured data end-to-end: subagents emit explicit claim-source mappings and the synthesis agent is required to preserve and merge them. This matches Anthropic's multi-agent best practice of structured outputs over fragile text-prefix conventions (A), costly post-hoc log analysis (B), or unreliable semantic-similarity reconstruction (D).", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-5.6"},
{"id": "ts-1.4-02", "q": "Users report that final reports sometimes lack depth on specific subtopics. Investigation shows that the document analysis agent frequently identifies gaps—for instance, noting \"the retrieved sources discuss API authentication but lack details on token refresh patterns\"—but under the current strict pipeline, this insight isn't actionable since search has already completed. What's the most effective architectural change?", "o": {"A": "Have the coordinator review analysis output for gap indicators and re-invoke search with gapinformed queries when gaps are detected.", "B": "Have the synthesis agent attach confidence scores to each section and flag areas with insufficient coverage for manual review.", "C": "Add a research planning agent before the search phase that decomposes topics into specific sub- questions.", "D": "Have the analysis agent report specific gaps to the coordinator, which triggers targeted searches and re-invokes analysis until sufficient."}, "a": "D", "w": "The core problem is a rigid one-way pipeline where gap insights arrive after search is finished, so the fix is a closed feedback loop: the analysis agent surfaces its specific gaps as structured output to the coordinator, which triggers targeted follow-up searches and re-runs analysis iteratively until coverage is sufficient. This matches Anthropic's orchestrator-worker agent pattern of iterating until a verifiable success criterion is met; option A is a weaker partial loop (coordinator inferring gaps from output, no re-analysis until sufficiency), while B and C don't make the gap insight actionable at runtime.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.4"},
{"id": "ts-1.3-03", "q": "After the web search and document analysis subagents complete their tasks, the coordinator needs to spawn the synthesis subagent to synthesize the findings. What is the correct approach for providing the synthesis subagent with the information it needs?", "o": {"A": "Provide the subagent with tool definitions that allow it to request outputs from other subagents via callbacks", "B": "Include the complete findings from both subagents directly in the synthesis subagent's prompt", "C": "Pass reference identifiers and configure the subagent with read access to a shared memory store where other subagents deposited their results", "D": "Spawn the subagent with only a brief task description, relying on automatic context inheritance from the coordinator"}, "a": "C", "w": "Anthropic's multi-agent best practice is for subagents to deposit their full outputs as artifacts in external/shared storage and pass lightweight references, so the synthesis subagent reads the prior results directly rather than receiving lossy or token-heavy copies through prompts. Callbacks between subagents (A) and automatic context inheritance (D) don't exist in this architecture, and inlining complete findings into the prompt (B) bloats context and risks information loss.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.3"},
{"id": "ts-1.2-02", "q": "A user is expanding the research system beyond its single web search agent by adding specialized data sources. They add a financial API agent that returns structured JSON with revenue, margins, and growth rates; a news monitoring agent that returns prose summaries of recent developments; and a patent analysis agent that returns structured lists of technology areas. The synthesis agent combines these into executive briefings. Currently, it converts everything to bullet points, causing financial comparisons to lose tabular clarity and news summaries to lose narrative flow. What change would most improve briefing quality?", "o": {"A": "Add a format conversion layer between subagents and synthesis that transforms all outputs to a common intermediate representation", "B": "Update the synthesis agent to render each content type appropriately—financial data as tables, news as prose", "C": "Standardize all subagent outputs to prose summaries with inline citations", "D": "Standardize all subagent outputs to JSON with fields for claim, evidence, source, and confidence"}, "a": "B", "w": "The quality loss comes from flattening heterogeneous content into one uniform format (bullets); options A, C, and D just repeat that mistake with a different uniform representation. The best fix is to make the synthesis agent format-aware, rendering each content type in its natural form—tables for financial comparisons, prose for news narratives—preserving the strengths of each subagent's output.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.2"},
{"id": "ts-1.2-03", "q": "The coordinator provides detailed step-by-step instructions to the web search subagent, specifying exact search queries, source priorities, and date filters. Production monitoring reveals three issues: (1) the subagent reports \"insufficient results\" rather than trying alternative approaches when pre-specified searches fail, (2) research quality drops for emerging topics that don't match expected patterns, and (3) the subagent rarely surfaces valuable tangential sources. What's the most effective way to improve subagent adaptability?", "o": {"A": "Specify research goals and quality criteria (coverage breadth, source diversity, recency) rather than procedural steps, letting the subagent determine its search strategy.", "B": "Remove procedural details entirely, delegating with simple goals like \"research X thoroughly\" and relying on the subagent's general capabilities.", "C": "Add explicit fallback directives to the detailed instructions: \"If specified searches yield fewer than N results, attempt alternative query formulations before reporting failure.\"", "D": "Implement a topic classification step where the coordinator categorizes requests as \"well-defined\" or \"exploratory\" and uses different instruction styles for each category."}, "a": "A", "w": "Anthropic's agent and multi-agent research guidance recommends delegating with clear objectives and success/quality criteria rather than prescriptive procedural scripts, letting the capable subagent adapt its own search strategy — which directly fixes all three observed failures. Option B removes necessary guidance entirely (under- specified delegation is a known failure mode), C patches only failure (1), and D adds coordinator complexity while keeping the brittle scripted approach.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.2"},
{"id": "ts-2.1-01", "q": "The document analysis agent has a single analyze_document tool that takes a document and a free-text instruction parameter. During evaluation, requests like \"extract the key financial metrics\" often return narrative summaries, while \"summarize the methodology\" sometimes returns raw data tables. The synthesis agent reports that 35% of analysis results require re-requests with clarified instructions. What's the most effective way to improve reliability?", "o": {"A": "Split the generic tool into purpose-specific tools — extract_data_points, summarize_content, verify_claim_against_source — each with defined input/output contracts", "B": "Have the coordinator pre-classify each analysis request before passing instructions to the document analysis agent", "C": "Keep the single tool but add an analysis_type enum parameter requiring explicit selection between extraction, summarization, and verification modes", "D": "Enhance the tool description with detailed examples showing how different instruction phrasings should map to different output formats"}, "a": "A", "w": "Anthropic's tool-design guidance for agents recommends narrowly-scoped, purpose-specific tools with explicit input/output contracts rather than one generic free-text tool. The failures here are output-format ambiguity across distinct task types (extraction vs. summarization vs. verification), which splitting into dedicated tools with defined contracts fixes structurally; an enum (C) or better descriptions (D) still leave a single loosely-specified output contract, and pre-classification (B) doesn't change the unreliable tool interface.", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-1.3-04", "q": "After the web search agent and document analysis agent complete their tasks, the coordinator invokes the synthesis agent. However, the synthesis agent responds that it cannot complete the task because no research findings were provided. What is the most likely cause of this issue?", "o": {"A": "The synthesis agent's context window is not large enough to hold the combined outputs from both previous agents.", "B": "The synthesis agent needs tools that can fetch results directly from the other agents' conversation histories.", "C": "The subagents need to share a single API connection to enable automatic context sharing between invocations.", "D": "The coordinator did not include the outputs from the previous agents in the synthesis agent's prompt."}, "a": "D", "w": "In a coordinator/orchestrator multi-agent pattern, each subagent call is a stateless API invocation with its own isolated context — there is no automatic context sharing between agents. The coordinator must explicitly inject the previous agents' outputs into the synthesis agent's prompt; failing to do so produces exactly this \"no research findings were provided\" response. Options A–C are wrong: a context-window overflow would cause a different error, and neither cross-agent history-fetching tools nor a shared API connection are how context is passed between agents.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.3"},
{"id": "ts-1.2-04", "q": "Production monitoring shows that follow-up queries like \"summarize what we learned about market trends\" consistently take 40+ seconds. Investigation reveals the coordinator spawns the synthesis subagent for each summarization request, passing 80K+ tokens of accumulated findings. The coordinator already has these findings in its context from orchestrating the research. What's the most effective way to improve response time for these follow-up summaries?", "o": {"A": "Pre-generate and cache summaries at multiple granularities whenever new findings accumulate.", "B": "Enable prompt caching on the synthesis subagent to reduce the overhead of repeatedly transferring the same research findings.", "C": "Have the coordinator handle straightforward summarization requests directly using its existing context, reserving subagent spawning for complex analytical tasks.", "D": "Spawn the synthesis subagent with reduced context and have it request specific findings from the coordinator on-demand."}, "a": "C", "w": "The coordinator already has all the findings in its context, so spawning a subagent and re-transferring 80K+ tokens per summary is pure latency overhead. Anthropic's multi-agent best practice is to delegate to subagents only when separate context windows or parallelism add value; simple summarization should be handled directly by the orchestrator, eliminating both the spawn cost and the token transfer.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.2"},
{"id": "ts-5.6-02", "q": "The synthesis agent receives summarized findings from the web search and document analysis agents, then passes a consolidated summary to the report generator. During testing, you discover the generated reports make factual claims without proper citations—the report generator cannot attribute statements to their original sources because that metadata was lost during the summarization steps. What's the most effective approach to ensure proper source attribution in the final reports?", "o": {"A": "Instruct the synthesis agent to embed source references inline within its summary text using a consistent citation format.", "B": "Have the report generator query the web search agent to re-locate sources for claims in the final report.", "C": "Skip summarization and pass full raw outputs from web search and document analysis directly to the report generator.", "D": "Have each agent output structured data separating content summaries from source metadata (URLs, document names, page numbers)."}, "a": "D", "w": "Structured outputs that explicitly separate summarized content from source metadata (URLs, document names, page numbers) guarantee provenance survives every handoff in the pipeline, which is the Anthropicrecommended pattern for multi-agent data flow. Inline citations in free text (A) are easily lost or mangled during downstream summarization, re-locating sources after the fact (B) is unreliable and can mis-attribute claims, and passing raw outputs (C) defeats the purpose of summarization and bloats the report generator's context.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.6"},
{"id": "ts-5.4-01", "q": "After the web search agent finds 25 sources (120K tokens of raw content), the document analysis agent extracts key insights (15K tokens), and the synthesis agent produces a coherent narrative draft (3K tokens), the coordinator must pass context to the report generation agent for the final output with proper source citations. What context-passing strategy provides the best balance of completeness and efficiency?", "o": {"A": "Pass only the synthesis draft and have a separate post-processing pipeline match claims to sources and insert citations after the report is generated.", "B": "Pass the synthesis draft along with a structured source index that maps key claims to their source URLs and relevant excerpts.", "C": "Pass a condensed summary of all prior stages that preserves the main findings and attributes them to sources by name only.", "D": "Pass the full accumulated context from all prior agents."}, "a": "B", "w": "Why it's correct: B. Correct. The synthesis gives the narrative; the source index gives the report generator exactly the binding it needs to cite without re-reading 120K tokens of raw content. Option breakdown: • A: Post-hoc matching is fragile — without the mapping the model used, you can't reliably bind claims to the right source. Hallucinated or misattributed citations are the usual failure mode. • B: Correct. The synthesis gives the narrative; the source index gives the report generator exactly the binding it needs to cite without re-reading 120K tokens of raw content. • C: Name-only attribution loses URLs and excerpts, so the report generator can't quote or verify — and 'by name only' tends to drift into vague citations. • D: Maximum completeness but wasteful — 120K+ tokens of raw search content is mostly irrelevant noise at the report-generation stage.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-1.2-05", "q": "The web search agent has gathered several relevant sources for a research topic. The document analysis agent now needs to examine these sources. How does information typically flow between these two specialized subagents?", "o": {"A": "The agents communicate through an event-driven message queue, with the document analysis agent subscribing to web search completion events.", "B": "The web search agent directly invokes the document analysis agent, passing the discovered sources as parameters.", "C": "The coordinator agent receives the web search agent's output and includes relevant findings in the prompt when invoking the document analysis agent.", "D": "Both agents access a shared memory store where the web search agent writes findings and the document analysis agent reads them."}, "a": "C", "w": "Why it's correct: C. Correct. In an orchestrator-worker pattern the coordinator is the hub. It collects each subagent's output and explicitly forwards the relevant parts into the next subagent's prompt. Option breakdown: • A: Event buses aren't part of the Claude subagent model. Subagents don't publish/subscribe to each other directly. • B: Subagents are isolated — they can't directly call sibling subagents. That would also tightly couple them and defeat the orchestrator pattern. • C: Correct. In an orchestrator-worker pattern the coordinator is the hub. It collects each subagent's output and explicitly forwards the relevant parts into the next subagent's prompt. • D: A shared store can be layered in as an optimization, but it's not how subagents typically communicate — and it introduces stale-read and consistency problems.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.2"},
{"id": "ts-5.6-03", "q": "When researching \"renewable energy adoption,\" the web search agent returns recent statistics (2024: 35% adoption) while the document analysis agent extracts data from internal reports (2022: 18% adoption). The synthesis agent incorrectly flags these as contradictory sources rather than recognizing the data shows growth over time. What change would best enable the synthesis agent to correctly interpret such temporal differences?", "o": {"A": "Require subagents to include publication or data collection dates in their structured outputs.", "B": "Add a conflict resolution agent that automatically discards older data when newer data exists for the same metric.", "C": "Configure the web search agent to only return results from the past 6 months.", "D": "Instruct the synthesis agent to always treat the most recent data as authoritative and place older findings in a separate historical appendix."}, "a": "A", "w": "Why it's correct: A. Correct. The synthesis agent misreads the data because it never sees the dates. Making each data point carry its own timestamp in the structured output lets synthesis reason about trends instead of contradictions. Option breakdown: • A: Correct. The synthesis agent misreads the data because it never sees the dates. Making each data point carry its own timestamp in the structured output lets synthesis reason about trends instead of contradictions. • B: Silently discarding older data destroys trend information — the very thing the question is asking about. • C: Shrinking the window throws away historical context and doesn't fix the architectural gap that metadata isn't being passed to synthesis. • D: Prompt instructions alone are unreliable and still hide temporal reasoning behind a rule. Structuring the data with dates is the systematic fix.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-5.6"},
{"id": "ts-5.6-04", "q": "Production reviews reveal inconsistent handling of uncertainty in final reports. Sometimes conflicting subagent findings are synthesized into a single confident statement (losing nuance), while other times reports over-hedge with excessive qualifications (becoming unhelpful). When the web search agent returns \"industry analysts estimate $50B market size (methodology varies)\" and the document analysis agent returns \"peer-reviewed study estimates 35B(±7B, 95% CI),\" the coordinator either picks one arbitrarily or produces vague statements like \"the market may be 35B−50B depending on factors.\" What systematic approach best addresses this?", "o": {"A": "Configure subagents to only report findings meeting a high-confidence threshold, filtering uncertain information before it reaches the coordinator.", "B": "Implement a confidence calibration layer that normalizes subagent uncertainty expressions to standardized probability scores (0.0-1.0), then weight-average findings by their calibrated confidence.", "C": "Instruct the synthesis agent to structure reports with explicit sections distinguishing well-established findings from contested ones, preserving original source characterizations and methodological context.", "D": "Add a verification subagent that cross-references findings across sources, only passing claims to synthesis that are corroborated by at least two independent sources."}, "a": "C", "w": "Why it's correct: C. Correct. Report structure that keeps methodological context and separates settled vs. contested claims is how you get nuance without over-hedging. Option breakdown: • A: Filtering throws away useful-but-uncertain evidence. It doesn't help the synthesis agent reason about conflicts — it just hides them. • B: Collapsing peer-reviewed CIs and analyst estimates into a single averaged number destroys the methodological difference that's the whole point. • C: Correct. Report structure that keeps methodological context and separates settled vs. contested claims is how you get nuance without over-hedging. • D: Two-source minimums drop legitimate single-source findings and don't resolve genuinely conflicting estimates with different methodologies.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-5.6"},
{"id": "ts-2.5-01", "q": "You're building a security scanning workflow. When engineers need to locate all occurrences of a dangerous function like eval() across a large codebase, which tool should your agent use for content search?", "o": {"A": "Use Glob with a pattern like /*eval* to find files, then Read each matching file.", "B": "Use Grep to search for the pattern \"eval(\" across all files in the codebase.", "C": "Read the project's main entry file and follow import statements to trace where eval might be used.", "D": "Use Bash to run ls -R | grep eval to recursively list files containing eval."}, "a": "B", "w": "Grep is the purpose-built content-search tool (ripgrep-based) for finding patterns inside file contents across a large codebase, which is exactly what locating all eval( call sites requires. Glob only matches file names, reading entry files and tracing imports doesn't scale or guarantee coverage, and ls -R | grep only matches file names, not file contents.", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-2.5"},
{"id": "ts-2.4-01", "q": "This currently requires manually copy-pasting content into conversations. The team wants the agent to access this standard Jira ticket data directly. What's the most effective approach?", "o": {"A": "Export Jira tickets to markdown files in the repository that the agent accesses using the Read tool.", "B": "Build a custom MCP server wrapping Jira's API with tools designed specifically for this team's code review workflow.", "C": "Integrate an existing Jira MCP server that exposes tickets, comments, and metadata through discoverable tool interfaces.", "D": "Use the Bash tool with curl to call Jira's REST API, including authentication headers and parsing JSON responses inline."}, "a": "C", "w": "For standard third-party service data like Jira tickets, Anthropic's recommended practice is to integrate an existing MCP server, which provides discoverable, typed tool interfaces with managed authentication. Building a custom MCP server (B) is unnecessary effort for standard ticket data, markdown exports (A) go stale and require manual syncing, and ad-hoc curl calls (D) are brittle and expose credentials inline.", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.4"},
{"id": "ts-2.5-02", "q": "Developer Productivity An engineer asks the agent to find all files in the monorepo that import the @company/auth package to understand how authentication is used across services. Which built-in tool is most appropriate for this task?", "o": {"A": "Bash, to execute find . -type d -name \"*auth*\" and explore matching directories", "B": "Read, starting with package.json files to trace dependency declarations", "C": "Grep, to search for the import statement pattern across file contents", "D": "Glob, to find files with \"auth\" in their filename or path"}, "a": "C", "w": "The task is to find every file whose contents contain an import of @company/auth, which is a content- search problem — exactly what the built-in Grep tool (ripgrep-based) is designed for. Glob and find/Bash only match filenames or directory names, which would miss the many importing files that don't have \"auth\" in their path, and reading package.json files only shows declared dependencies, not actual usage sites.", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-2.5"},
{"id": "ts-2.4-02", "q": "Your productivity agent connects to three MCP servers: an issue tracker (search_issues, get_issue, create_comment), a documentation wiki (search_docs, get_page, list_spaces), and a database explorer (run_query, get_schema, list_databases). When engineers ask cross-system questions like \"What database tables are affected by the authentication refactor in PROJ-1234?\", monitoring shows the agent makes 8-10 sequential tool calls, frequently issues exploratory calls because it lacks visibility into what content each server contains, and exhausts context space before completing complex investigations. What architectural change best leverages MCP capabilities to address these issues?", "o": {"A": "Consolidate all three servers into a unified MCP server with cross-referencing capabilities", "B": "Expose each server's content catalog as MCP resources—issue summaries, documentation hierarchy, database schemas", "C": "Add a prepare_investigation tool to each server that accepts a natural language question and returns relevant content summaries", "D": "Add an orchestrator that routes questions to a single server based on keywords"}, "a": "B", "w": "MCP resources are the protocol primitive designed for exactly this problem: servers expose browsable, application-controlled context (issue summaries, doc hierarchies, database schemas) that the agent can discover and read without exploratory tool-call round trips, directly fixing the visibility gap and context exhaustion. A rebuilds a monolith against MCP's composable design, C just adds more tools without leveraging MCP capabilities, and D's single-server keyword routing breaks inherently cross-system questions.", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.4"},
{"id": "ts-2.3-01", "q": "During testing, agents frequently call tools outside their specialization—the synthesis agent attempts web searches, and the report generator tries to analyze documents. What is the primary cause of this poor tool selection behavior?", "o": {"A": "Choosing from 18 tools instead of 4-5 relevant ones increases decision complexity beyond reliable selection thresholds.", "B": "The coordinator cannot track which capabilities each subagent has, leading to misrouted tasks.", "C": "The agents' role descriptions in their system prompts conflict with having access to tools outside that role.", "D": "The tool definitions consume too much context window space, leaving insufficient room for task content."}, "a": "A", "w": "Anthropic's agent best practices recommend giving each subagent only a small, role-relevant tool set, because tool selection accuracy degrades as the number of available (especially irrelevant) tools grows. With all 18 tools exposed to every agent, the model faces a larger decision space and predictably picks tools outside its specialization — the root cause is selection complexity, not coordinator tracking, prompt conflicts, or contextwindow exhaustion.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-2.3"},
{"id": "ts-5.1-01", "q": "A customer returns 4 hours after their initial session about the same billing dispute. The previous 32-turn session contains lookup_order results showing \"Status: PENDING, Expected resolution: 24-48 hours.\" In testing, you observe that when resuming sessions with stale tool results, the agent often references the outdated data in responses (e.g., \"I see your refund is still being processed\") even after subsequent fresh tool calls return different information. What approach most reliably handles returning customers?", "o": {"A": "Resume with full history but filter out previous tool_result messages before resuming, keeping only the human/assistant turns so the agent must re-fetch needed data.", "B": "Start a new session, inject a structured summary of the previous interaction (issue type, actions taken, resolution status), then make fresh tool calls before engaging.", "C": "Resume with full history and add a system prompt instruction telling the agent to always prefer the most recent tool results when multiple calls to the same tool exist in context.", "D": "Resume with full history and configure the agent to automatically re-call all previously-used tools at session start to ensure data freshness."}, "a": "B", "w": "Why it's correct: B. Correct. A clean session with a summary keeps the narrative continuity while guaranteeing the agent isn't reasoning over stale tool results. Option breakdown: • A: Stripping tool_results from the middle of a conversation can leave assistant messages referencing nonexistent results — the transcript becomes internally inconsistent. • B: Correct. A clean session with a summary keeps the narrative continuity while guaranteeing the agent isn't reasoning over stale tool results. • C: Prompt instructions are suggestions. You observed that exact failure mode in testing — the model still references old results. • D: Blanket re-calling is wasteful, slow, and still leaves the old results sitting in context to confuse the model.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.2-01", "q": "You're implementing the escalation logic for when the agent should call escalate_to_human. Your team proposes four different approaches for triggering escalation. Which approach will most reliably identify cases that genuinely require human intervention?", "o": {"A": "Instruct the agent to escalate when the customer requests a human, when the issue requires policy exceptions, or when the agent cannot make meaningful progress.", "B": "Configure the agent to escalate after three consecutive tool calls that fail to resolve the customer's stated issue, ensuring a reasonable attempt before involving a human.", "C": "Implement sentiment analysis that monitors for frustration indicators (negative language, repeated questions, exclamation marks) and trigger escalation when the frustration score exceeds a configured threshold.", "D": "Build a rules engine that maps specific issue types, customer segments, and product categories to escalation decisions, removing the need for model judgment calls."}, "a": "A", "w": "Why it's correct: A. Correct. Escalation decisions are judgment calls about intent and progress — exactly what LLMs are good at. Clear criteria in natural language outperform rigid rules for the long tail. Option breakdown: • A: Correct. Escalation decisions are judgment calls about intent and progress — exactly what LLMs are good at. Clear criteria in natural language outperform rigid rules for the long tail. • B: A hard retry count fires both too early (legitimate retries) and too late (obvious policy issues on the first call). • C: Sentiment can catch frustration but misses calm customers who simply need a human for a policy exception, and over-escalates on stylistic language. • D: Rules engines break on the cases they weren't designed for — and customer support is full of those.", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-5.2-02", "q": "After investigating a billing dispute over 25+ turns, you've identified that duplicate charges occurred due to a payment gateway timeout triggering retry logic. The required refund ($847) exceeds your $500 authorization limit. You need to call escalate_to_human, and the human agent won't have access to your conversation transcript. What context should you pass to enable effective resolution?", "o": {"A": "The customer's original complaint verbatim plus the tool result excerpts showing duplicate transactions.", "B": "A structured summary: customer ID, root cause, refund amount, and recommended action.", "C": "The complete conversation transcript with all tool results.", "D": "Your diagnosis and the refund amount only."}, "a": "B", "w": "Why it's correct: B. Correct. A structured handoff with identifiers, cause, amount, and recommended action is what a human agent needs to pick up the case instantly without re-investigating. Option breakdown: • A: Raw artifacts without synthesis force the human to re-do the 25 turns of investigation you just finished. • B: Correct. A structured handoff with identifiers, cause, amount, and recommended action is what a human agent needs to pick up the case instantly without re-investigating. • C: Dumping the whole transcript forces the human to wade through 25 turns instead of reading a one-screen brief. • D: Missing customer identifiers and recommended action — the human can't act without them.", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-1.5-01", "q": "Compliance requires that refunds exceeding $500 must automatically escalate to a human agent—this rule cannot be left to model discretion. Despite clear system prompt instructions, production logs show the agent occasionally processes high-value refunds directly (3% failure rate). How should you achieve guaranteed compliance?", "o": {"A": "Modify the refund tool to return an error with message \"Amount exceeds policy limit—please escalate\" when threshold is exceeded.", "B": "Add few-shot examples to the prompt showing correct escalation behavior at various refund amounts ($400, $500, $600).", "C": "Implement a hook to intercept tool calls; when the refund process amount exceeds $500, block it and invoke human escalation.", "D": "Strengthen the system prompt with emphatic language: \"CRITICAL POLICY: Refunds over $500 MUST trigger human escalation. NEVER process these directly.\""}, "a": "C", "w": "Why it's correct: C. Correct. Compliance-grade rules belong outside the model — a deterministic hook on the tool call is guaranteed to fire every time, independent of model behavior. Option breakdown: • A: This helps, but depends on the agent interpreting the error correctly and escalating — still model discretion at the decision point. • B: Few-shots shift the distribution but don't remove the 3% failure. Compliance says the rule can't be left to model discretion. • C: Correct. Compliance-grade rules belong outside the model — a deterministic hook on the tool call is guaranteed to fire every time, independent of model behavior. • D: Emphatic prompts reduce but don't eliminate misuse. 'Cannot be left to model discretion' rules out any prompt-only solution.", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-1.5"},
{"id": "ts-2.2-01", "q": "During a billing dispute resolution, your agent successfully retrieves customer info via get_customer and order details via lookup_order, but when attempting to call process_refund, the tool returns a timeout error. The agent has enough information to explain the charges and verify refund eligibility, but cannot actually process the refund due to the backend failure. What approach best balances first-contact resolution with appropriate error handling?", "o": {"A": "Escalate immediately to a human agent since the refund action cannot be completed", "B": "Implement automatic retries with exponential backoff for process_refund, keeping the conversation open until the refund is successfully processed", "C": "Explain the billing, confirm refund eligibility, acknowledge the system issue preventing immediate processing, and offer escalation or retry later", "D": "Confirm the refund will be processed and close the conversation, since the system has all necessary information to complete it automatically"}, "a": "C", "w": "Why it's correct: C. Correct. Deliver the partial value you can (explanation + eligibility), be honest about the failure, and let the customer choose between human escalation or a retry. Classic graceful degradation. Option breakdown: • A: Punts a transient backend issue to a human when the agent could still explain the situation and offer options. • B: Forcing the customer to wait on indefinite retries is poor UX and may never succeed if the outage is long-lived. • C: Correct. Deliver the partial value you can (explanation + eligibility), be honest about the failure, and let the customer choose between human escalation or a retry. Classic graceful degradation. • D: Committing to an outcome that didn't happen is misleading the customer — a bigger failure than the timeout.", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-5.2-03", "q": "A customer writes: \"I've been going back and forth on this return for days. I just want to speak to someone who can actually help me.\" The agent has confirmed via lookup_order that the return is straightforward—within policy and eligible for immediate processing. What should the agent do?", "o": {"A": "Acknowledge frustration, inform them this is resolvable now, and offer to complete it or escalate", "B": "Call escalate_to_human immediately to honor the customer's request", "C": "Process the refund via process_refund to resolve the underlying issue, then inform them it's complete", "D": "Ask what specifically hasn't worked in previous attempts before deciding whether to escalate or resolve automatically"}, "a": "A", "w": "Why it's correct: A. Correct. Honor the feeling, give them the fast resolution path in writing, and preserve their choice. That's the customer-respect move that still leverages the agent's capability. Option breakdown: • A: Correct. Honor the feeling, give them the fast resolution path in writing, and preserve their choice. That's the customer-respect move that still leverages the agent's capability. • B: Unnecessary queueing when the issue is one tool call away. Frustrates the customer further by adding waiting to an already-simple case. • C: Takes unilateral action after the customer explicitly asked to speak to someone — overrides their stated preference. • D: Interrogating a frustrated customer about past failures is the opposite of what they asked for.", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-5.1-02", "q": "The agent verifies customer identity through a multi-step process before resetting passwords. During testing, you notice that after the customer answers the third verification question, the agent asks them to provide their name again, as if the earlier exchange never happened. What's the most likely cause of this behavior?", "o": {"A": "The verification tool is clearing the agent's internal state after each successful validation step.", "B": "The prompt lacks instructions telling Claude to remember information across multiple exchanges.", "C": "The conversation history isn't being passed in subsequent API requests.", "D": "Claude's memory retention is limited to two conversational turns by default, requiring explicit configuration to extend it."}, "a": "C", "w": "Why it's correct: C. Correct. The API is stateless. Each request must include the full messages array. If you only send the latest turn, the model has no memory of earlier ones — exactly the 'ask for the name again' symptom. Option breakdown: • A: Tools don't clear agent state — conversation state lives in the messages array you send. • B: Memory across turns isn't achieved by an instruction — it comes from passing the prior turns into the next request. • C: Correct. The API is stateless. Each request must include the full messages array. If you only send the latest turn, the model has no memory of earlier ones — exactly the 'ask for the name again' symptom. • D: No such default limit exists. Context is bounded by the window, and history length is under your control.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-2.2-02", "q": "Production logs reveal inconsistent error handling: when lookup_order fails, the agent sometimes retries 5+ times (wasteful when the order ID doesn't exist), sometimes escalates immediately (premature for temporary network issues), and sometimes asks users for clarification (inappropriate when the issue is a backend permission error). Investigation shows your MCP tool returns uniform error responses: {\"isError\": true, \"content\": [{\"type\": \"text\", \"text\": \"Operation failed\"}]}. The agent cannot distinguish between error types. What's the most effective improvement?", "o": {"A": "Enhance error responses with structured metadata: include errorCategory (transient/validation/permission), isRetryable boolean, and a description of what caused the failure.", "B": "Create an analyze_error MCP tool the agent calls after any failure to determine the error category and recommended action.", "C": "Implement retry logic with exponential backoff in your MCP server for all errors, returning to the agent only after retries are exhausted.", "D": "Add few-shot examples to the system prompt demonstrating how to interpret error message patterns and select appropriate responses for each."}, "a": "A", "w": "Why it's correct: A. Correct. Give the agent the information it needs to make the right decision: category, retryability, and a human-readable cause. That replaces guessing with deterministic policy. Option breakdown: • A: Correct. Give the agent the information it needs to make the right decision: category, retryability, and a human-readable cause. That replaces guessing with deterministic policy. • B: Adds an extra round-trip for something the original tool already knows. Put the metadata in the original response. • C: Blanket retries hurt on permanent errors (order not found) and hide useful distinctions from the agent. • D: If the tool returns 'Operation failed' for every failure, no amount of few-shots can extract category info that isn't there.", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-1.1-02", "q": "When the agent calls lookup_order and receives order details showing the item was purchased 45 days ago, how does the agentic loop determine whether to call process_refund or escalate_to_human next?", "o": {"A": "The orchestration layer automatically routes to the next tool based on the order's status field.", "B": "The agent follows a pre-configured decision tree mapping order attributes to specific tool calls.", "C": "The order details are added to the conversation and the model reasons about which action to take.", "D": "The agent executes the remaining steps in a tool sequence planned at the start of the request."}, "a": "C", "w": "Why it's correct: C. Correct. The agentic loop works by appending tool_result messages to the conversation and letting the model decide the next step on each turn. That's how 45 days refund vs. escalate gets resolved. Option breakdown: • A: There's no implicit orchestration layer picking tools from a field. The model drives tool selection. • B: Agentic loops are model-driven, not decision-tree-driven. Hardcoded trees are the opposite of what the agent pattern is for. • C: Correct. The agentic loop works by appending tool_result messages to the conversation and letting the model decide the next step on each turn. That's how 45 days refund vs. escalate gets resolved. • D: There's no upfront, committed plan — the agent chooses each next step based on the latest context.", "c": "Agent vs. Workflow Design", "dup": "", "conflict": false, "ts": "ts-1.1"},
{"id": "ts-5.2-04", "q": "A customer sends: \"This is frustrating. I've explained my issue twice and nothing is being resolved. I want to talk to a real person NOW.\" The agent has not yet called any tools to investigate their account. What should the agent do?", "o": {"A": "Acknowledge the frustration and ask one targeted question to understand the specific issue before escalating.", "B": "Briefly explain what the agent can help with and offer to resolve the issue quickly, escalating only if the customer repeats their request.", "C": "Immediately call escalate_to_human with the conversation history.", "D": "First call get_customer and lookup_order to gather account context, then escalate to a human agent."}, "a": "A", "w": "Why it's correct: A. Correct. The customer has said 'twice' but you have no context yet. One acknowledging, focused question gives you a shot at first-contact resolution without dismissing the frustration or delaying a potential handoff. Option breakdown: • A: Correct. The customer has said 'twice' but you have no context yet. One acknowledging, focused question gives you a shot at first-contact resolution without dismissing the frustration or delaying a potential handoff. • B: Launching into capability-listing at a frustrated customer who asked for a human reads as dismissive. • C: Escalating with zero tool context creates a cold handoff where the human also starts from scratch. • D: Investigating without asking adds latency and doesn't respect the customer's request. A single acknowledging question is faster and more respectful.", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-5.2-05", "q": "Your agent is handling a billing dispute. After calling get_customer and lookup_order, it identifies that the dispute involves a promotional pricing error requiring manager approval—beyond the agent's authorization level. How should the workflow handle this mid-process escalation?", "o": {"A": "Call escalate_to_human passing only the customer's original message.", "B": "Compile a structured handoff with customer details, order info, and the identified issue before calling escalate_to_human.", "C": "Attempt the refund with process_refund anyway, escalating only if the system rejects the transaction.", "D": "Persist the complete conversation and tool response history to a database, then call escalate_to_human with a reference ID."}, "a": "B", "w": "Why it's correct: B. Correct. A structured brief (who, what order, what issue, why it exceeds auth) lets the human agent pick up instantly. That's the mid-process escalation pattern. Option breakdown: • A: Drops the tool-derived context the agent just gathered, forcing the human to re-do the investigation. • B: Correct. A structured brief (who, what order, what issue, why it exceeds auth) lets the human agent pick up instantly. That's the mid-process escalation pattern. • C: Knowingly exceeding authorization is a policy violation — not something to try and hope the system catches. • D: Adds infrastructure and an extra lookup step when an inline structured brief is simpler and faster.", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-5.1-03", "q": "A customer raises three separate issues during one session: a refund inquiry (turns 1-15), a subscription question (turns 16-30), and a payment method update (turns 31-45). At turn 48, the customer asks \"What happened with my refund?\" The conversation is approaching context limits. What strategy best maintains the agent's ability to address all issues throughout the session?", "o": {"A": "Extract and persist structured issue data (order IDs, amounts, statuses) into a separate context layer.", "B": "Rely on MCP tools to re-fetch relevant information on demand when the customer references earlier issues.", "C": "Summarize earlier turns into a narrative description, preserving full message history only for the active issue.", "D": "Implement sliding window context that retains the most recent 30 turns."}, "a": "C", "w": "Why it's correct: C. Correct. Progressive summarization compresses stable resolved topics while keeping the active thread verbatim — the classic pattern for long multi-issue conversations near the context limit. Option breakdown: • A: A sidecar context layer adds engineering and doesn't naturally preserve the conversational narrative the customer expects. • B: Re-fetching is fine for freshness, but it doesn't solve the context-length problem — and you lose what was said between the customer and the agent. • C: Correct. Progressive summarization compresses stable resolved topics while keeping the active thread verbatim — the classic pattern for long multi-issue conversations near the context limit. • D: A pure sliding window silently drops the refund issue (turns 1–15) from context, which is exactly what the customer is asking about.", "c": "Context & Memory Management", "dup": "", "conflict": true, "ts": "ts-5.1"},
{"id": "ts-2.2-03", "q": "When implementing your lookup_order MCP tool, the backend sometimes returns errors (e.g., \"Order not found\" or temporary database failures). What is the correct pattern for communicating these errors back to the agent?", "o": {"A": "Log the error server-side and return an empty result to avoid confusing the model", "B": "Return the error message in the tool result content with the isError flag set to true", "C": "Throw an exception from the tool handler so the agent framework can catch and log it", "D": "Return a success response with a \"status\" field indicating the error type"}, "a": "B", "w": "Why it's correct: B. Correct. MCP's designed pattern: put the error text in the content field and mark isError=true. Claude sees both the failure flag and a readable message to reason about. Option breakdown: • A: Returning empty successes makes the agent think no data exists, rather than that something went wrong — a different and worse confusion. • B: Correct. MCP's designed pattern: put the error text in the content field and mark isError=true. Claude sees both the failure flag and a readable message to reason about. • C: Uncaught exceptions break the tool protocol and don't give the model anything to reason with. • D: Ad-hoc 'status' fields vary across tools and the model has no standard way to interpret them. isError is the standard.", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-2.2-04", "q": "Your process_refund tool returns two types of errors: technical errors (\"503 Service Unavailable\", \"Connection timeout\") that are transient (5% of calls), and business errors (\"Order exceeds 30-day return window\", \"Item already refunded\") that are permanent (12% of calls). Monitoring shows the agent wastes 3-4 turns retrying business errors that can never succeed. Currently, both error types return only a plain text message to Claude. What's the most effective way to reduce wasted retries while improving customer-facing response quality?", "o": {"A": "Return structured error responses with retryable: false for business errors and a customer-friendly explanation for Claude to use.", "B": "Add few-shot examples showing how to distinguish retryable from non-retryable errors by parsing error message text.", "C": "Add a check_refund_eligibility tool that must be called before process_refund to prevent business rule violations.", "D": "Implement automatic retry logic at the tool level for technical errors only, passing business errors to Claude without retries."}, "a": "A", "w": "Why it's correct: A. Correct. A retryable flag tells Claude deterministically 'don't retry,' and a ready-made customer-friendly message improves the outgoing reply. Fixes both problems at once. Option breakdown: • A: Correct. A retryable flag tells Claude deterministically 'don't retry,' and a ready-made customer-friendly message improves the outgoing reply. Fixes both problems at once. • B: Relying on the model to text-parse error strings is fragile and exactly the instability you see today. • C: Useful in principle but adds a round-trip to every refund to guard against 12% of cases, and doesn't help when process_refund still fails for other business reasons. • D: Hiding transient retries inside the tool can mask latency and takes the model out of the loop on recovery decisions. Business errors also still arrive as a plain string, so the customer-facing response doesn't improve.", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-5.1-04", "q": "Your agent has called lookup_order multiple times while investigating a customer's return requests. Each response includes 40+ fields (items, shipping details, payment info, status history). Tool outputs now represent the majority of the conversation's context. The customer mentions two more orders they want to discuss. What's the most effective approach before making additional lookups?", "o": {"A": "Extract only return-relevant fields (items, purchase date, return window, status) from each existing order response, removing verbose details", "B": "Have the model generate a natural language summary of each order's key details, replacing structured responses with prose descriptions", "C": "Move all tool responses to a vector database with semantic indexing, retrieving relevant portions as the conversation continues", "D": "Proceed with additional lookups without modifying the existing tool output context"}, "a": "A", "w": "Why it's correct: A. Correct. Keep the fields that matter for the task and drop the rest. This directly addresses the context-bloat problem before you add two more lookups. Option breakdown: • A: Correct. Keep the fields that matter for the task and drop the rest. This directly addresses the context-bloat problem before you add two more lookups. • B: Prose summaries lose precision for fields the model may need later (exact dates, amounts). Structured pruning is better than paraphrasing. • C: A vector DB is heavy infrastructure for what is essentially a pruning problem. • D: Does nothing about the bloat — you're heading for context exhaustion.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-1.1-03", "q": "During initial testing of the automated review pipeline, you notice that reviews on large PRs (50+ changed files) sometimes take over 20 minutes and cost $8-12 per run due to extensive agentic loops — Claude reads files, runs analysis tools, and iterates many times. Your team needs each invocation to abort once it reaches a fixed iteration count and a fixed dollar amount, enforced by Claude Code itself rather than the surrounding job runner. Which configuration change directly enforces both of those per-invocation caps?", "o": {"A": "Add --max-turns 10 --max-budget-usd 2.00 to the claude -p invocation to cap iterations and spend.", "B": "Switch the --model flag to a smaller, cheaper model so each iteration uses fewer tokens and lower per- call cost.", "C": "Set timeout-minutes: 5 on the GitHub Actions job step and monitor per-run costs via the Anthropic Console usage dashboard.", "D": "Set --permission-mode dontAsk to auto-deny any tool permission requests not in the explicitly allowed set."}, "a": "A", "w": "Claude Code's --max-turns flag caps the number of agentic iterations and --max-budget-usd caps per- invocation dollar spend, both enforced natively by Claude Code in headless (claude -p) mode — exactly the two per-invocation limits required. Option C relies on the surrounding job runner (GitHub Actions timeout) and passive dashboard monitoring, which the question explicitly excludes, while B only lowers cost without enforcing any cap and D governs tool permissions, not iterations or spend.", "c": "Agent vs. Workflow Design", "dup": "", "conflict": false, "ts": "ts-1.1"},
{"id": "ts-3.5-01", "q": "Your test generation produces unit tests for new code, but reviews show 55% are low-value: trivial assertions that only verify functions don't throw exceptions, tests duplicating existing coverage, or tests ignoring your team's fixture conventions. How do you reduce the rate of low-value tests being generated in the first place?", "o": {"A": "Add post-generation coverage analysis that automatically filters out any generated test that doesn't increase line coverage beyond what existing tests provide.", "B": "Restrict test generation to directories where historical quality metrics show higher acceptance rates, disabling it for areas where generated tests consistently require heavy editing.", "C": "Document testing standards in CLAUDE.md including valuable test criteria, available fixtures with intended use cases, and examples distinguishing meaningful behavioral tests from trivial assertions.", "D": "Implement a two-phase generation where a second Claude call scores each test against quality criteria, filtering out low-scoring tests before presenting results to developers."}, "a": "C", "w": "The question explicitly asks how to reduce low-value tests \"being generated in the first place,\" which means fixing the upstream cause: Claude lacks context about what the team considers a valuable test. Documenting testing standards, fixture usage, and good-vs-trivial examples in CLAUDE.md gives Claude that context at generation time, whereas A and D only filter bad output after the fact and B avoids the problem rather than solving it.", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-3.5"},
{"id": "ts-1.7-02", "q": "An engineer used Claude Code yesterday to investigate authentication flows in a legacy monolith, building up significant context over a 2-hour session. Today she wants to continue that specific investigation. She's worked on three other codebases since then and knows the session was named \"auth-deep-dive\". How should she resume?", "o": {"A": "Use --continue to pick up where the most recent conversation left off", "B": "Use --resume auth-deep-dive to load that specific session by name", "C": "Use --session-id with the UUID from yesterday's session transcript file", "D": "Start fresh and re-read the same files"}, "a": "B", "w": "Claude Code's --resume flag accepts a session name or ID, so --resume auth-deep-dive loads that exact named session with all its accumulated context. --continue only resumes the most recent conversation, which would be one of the other sessions she's worked on since, and manually hunting for a UUID or starting fresh discards the value of the named session.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-1.7"},
{"id": "ts-2.1-02", "q": "After integrating a local MCP server providing code analysis tools (analyze_dependencies, find_dead_code, calculate_complexity), you verify the server is healthy and tools appear in the tools/list response. However, you observe that the agent consistently uses Grep to search for import statements instead of calling analyze_dependencies—even when users explicitly ask about \"code dependencies.\" Examining tool definitions reveals: - MCP: analyze_dependencies — \"Analyzes dependency graph\" - Built-in: Grep — \"Search file contents for a pattern using regular expressions. Returns matching lines with line numbers and surrounding context.\" What's the most effective approach to improve the agent's selection of MCP tools?", "o": {"A": "Remove Grep from available tools when the MCP server is connected to eliminate functional overlap.", "B": "Split analyze_dependencies into granular tools (list_imports, resolve_transitive_deps, detect_circular_deps) so each has a focused purpose less likely to overlap with Grep.", "C": "Add routing instructions to the system prompt specifying that dependency-related questions should use MCP tools rather than Grep.", "D": "Expand MCP tool descriptions to detail capabilities and outputs—e.g., \"Builds dependency graph showing direct imports, transitive dependencies, and cycles.\""}, "a": "D", "w": "The root cause is the asymmetry in tool descriptions: the MCP tool's vague \"Analyzes dependency graph\" loses to Grep's detailed, concrete description, so the agent picks Grep. Anthropic's tool-use best practices say the tool description is the primary lever for tool selection—writing detailed descriptions of capabilities, outputs, and when to use the tool (option D) fixes selection at the source, whereas removing Grep, fragmenting the tool, or adding brittle system-prompt routing rules are workarounds.", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.5-03", "q": "An engineer asks the agent to find all callers of a function before removing it. The function is defined in a core library but is also exposed through wrapper modules that rename the function for domain-specific use (e.g., calculateTax in the library becomes computeOrderTax in the orders module). What exploration strategy will most reliably identify all callers?", "o": {"A": "Search for the function name in project documentation to understand intended usage patterns and navigate to documented integration points.", "B": "Use Grep to search for the function's original name across the codebase.", "C": "Read the library and wrapper modules to identify all exposed names for the function, then Grep for each name across the codebase.", "D": "Use Grep to find all files that import from the library or wrapper modules, then read each file to check whether it uses the function."}, "a": "C", "w": "Because the function is re-exported under different names by wrapper modules, grepping only the original name (B) misses aliased callers, and documentation (A) may be stale or incomplete. The reliable strategy is to first read the library and wrappers to enumerate every exposed name/alias, then Grep for each name across the codebase (C); option D is indirect and far more laborious, requiring a manual read of every importing file.", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-2.5"},
{"id": "ts-1.7-03", "q": "An engineer's exploration subagent spent 30 minutes analyzing a legacy payment system, reading 47 files and documenting data flows. The session was interrupted when the engineer's connection dropped. While away, a teammate merged a PR that renamed two utility functions. The engineer wants to continue the same exploration. What's the most effective approach?", "o": {"A": "Resume the subagent from its previous transcript and inform it about the renamed functions.", "B": "Launch a fresh subagent and include the prior transcript in the initial prompt for context.", "C": "Launch a fresh subagent with a summary of prior findings.", "D": "Resume the subagent from its previous transcript without mentioning the changes—the architecture understanding remains valid."}, "a": "A", "w": "Resuming from the saved transcript preserves all 30 minutes of accumulated exploration context (47 files, documented data flows) without re-spending tokens, and explicitly telling the agent about the renamed utility functions corrects the only part of its knowledge that became stale. D leaves the agent operating on outdated function names, B wastefully stuffs an entire transcript into a fresh context window, and C discards detailed file-level understanding.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-1.7"},
{"id": "ts-5.4-02", "q": "An engineer now asks it to understand how the physics engine integrates with rendering for collision debug overlays. You notice recent responses reference \"typical rendering patterns\" rather than the specific VulkanPipeline and FrameGraph classes it discovered earlier. What's the most effective approach?", "o": {"A": "Use /clear to reset context completely, then start fresh with physics exploration using file paths from the project's CLAUDE.md.", "B": "Spawn a sub-agent to explore physics independently, then manually synthesize its findings with the rendering knowledge accumulated in the main conversation.", "C": "Summarize key rendering findings, then spawn a sub-agent for physics exploration with that summary in its initial context.", "D": "Continue in the current context with more targeted prompts referencing the specific classes by name."}, "a": "C", "w": "The generic \"typical rendering patterns\" responses signal context degradation from a long, bloated session, so the fix is to compact the valuable rendering knowledge into a summary and hand it to a sub-agent with a fresh context for the physics task. This follows Anthropic's context-management best practice of summarization plus sub-agents with clean contexts, preserving the specific VulkanPipeline/FrameGraph findings that the integration task depends on, unlike A (loses knowledge), B (sub-agent lacks needed rendering context and synthesis happens in the degraded context), or D (continues in a degraded context).", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-5.4-03", "q": "An engineer asks the agent to understand how the caching layer works before adding a new cache invalidation trigger. After initial Grep searches, the agent has identified that caching logic spans 15 files including decorators, middleware, and service classes (~8,000 lines total). What's the most effective next step for building understanding while managing context constraints?", "o": {"A": "Use Glob to find files matching common caching patterns (cache.py, caching/), prioritize the largest files by reading them first, then check smaller files for gaps.", "B": "Use the Read tool to sequentially load all 15 files, building complete understanding across the full caching implementation.", "C": "Use Grep to search for \"invalidate\" and \"expire\" patterns across all files, then Read only those specific line ranges with minimal surrounding context.", "D": "Analyze imports and class hierarchies to identify the base cache class, Read that file to understand the interface, then trace specific invalidation implementations."}, "a": "D", "w": "Starting from the base cache class gives the agent the core abstraction and interface that all 15 files build on, then tracing only the relevant invalidation implementations yields deep structural understanding with minimal context usage. Reading all files (B) wastes context, size-based prioritization (A) is arbitrary, and keyword-only line- range reads (C) produce fragmentary knowledge inadequate for safely adding a new invalidation trigger.", "c": "Cost & Latency", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-1.7-04", "q": "Your agent has analyzed a complex service module—reading 23 source files, tracing request flows, and identifying error handling patterns. A developer wants to compare two testing strategies before committing to one: end-to-end tests with mocked external services vs. snapshot tests capturing expected outputs. They need to independently develop both approaches to evaluate trade-offs. How should you manage the sessions?", "o": {"A": "Export the analysis session's key findings to a file, then create two new sessions that reference this file.", "B": "Resume the analysis session with fork_session enabled, creating a separate branch for each testing strategy.", "C": "Start two fresh sessions, having each re-read the relevant source files before beginning.", "D": "Continue in the original session, developing end-to-end tests first, then snapshot tests sequentially."}, "a": "B", "w": "Resuming the analysis session with fork_session (CLI --fork-session / Agent SDK fork_session=True with resume) branches the session into new session IDs while preserving the full analysis context and leaving the original intact. Forking twice gives each testing strategy the complete 23-file analysis with no re-work, and the two branches develop completely independently — exactly the stated requirement. Exporting to a file is lossy, fresh sessions discard the analysis, and a single sequential session is neither independent nor unbiased.", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-1.7"},
{"id": "ts-1.7-05", "q": "Your codebase exploration tool stores session IDs to allow engineers to continue investigations across work sessions. An engineer spent an hour yesterday analyzing a legacy authentication module, building context about its architecture and dependencies. They want to continue today. The session ID is valid, but version control shows 3 of the 12 files the agent previously read were modified overnight by a teammate's merge. What approach best balances efficiency and accuracy?", "o": {"A": "Resume the session and immediately have the agent re-read all 12 previously analyzed files", "B": "Start a fresh session to ensure the agent works with current codebase state without stale assumptions", "C": "Resume the session and inform the agent which specific files changed for targeted re-analysis", "D": "Resume the session without informing the agent about the changed files"}, "a": "C", "w": "Resuming the session preserves the hour of accumulated context about the module's architecture (efficiency), while telling the agent exactly which 3 files changed allows targeted re-reading of only the stale files (accuracy). Re-reading all 12 files (A) wastes tokens, starting fresh (B) throws away valuable context, and resuming silently (D) risks the agent acting on stale file contents.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-1.7"},
{"id": "ts-5.4-04", "q": "During testing, you observe that in extended exploration sessions (30+ minutes), the agent starts giving inconsistent answers about code structure it discussed earlier. Engineers report having to repeat context about modules they've already explored. What's the most effective approach to address this?", "o": {"A": "Have the agent maintain a scratchpad file that records key findings, referencing it for subsequent questions.", "B": "Switch to a higher-capacity model tier to provide more context window space for accumulated exploration data.", "C": "Implement automatic context clearing every 15 minutes to ensure the agent starts with fresh, uncontaminated context.", "D": "Create summaries of all source files before exploration begins, loading only these compressed representations into context."}, "a": "A", "w": "Why it's correct: A. Correct. A scratchpad offloads findings to durable storage the agent can re-read on demand, giving it a stable 'memory' independent of how crowded the context window gets. Option breakdown: • A: Correct. A scratchpad offloads findings to durable storage the agent can re-read on demand, giving it a stable 'memory' independent of how crowded the context window gets. • B: A bigger window delays the problem but doesn't solve attention degradation over long, noisy contexts. • C: Wholesale clearing throws away valid findings — exactly the state engineers complain about having to re-establish. • D: Pre-summaries lose the detail that makes code exploration useful and often misrepresent files the engineer cares about most.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-1.7-06", "q": "An engineer used the agent yesterday to analyze a legacy authentication module, identifying two distinct refactoring approaches: extracting a microservice versus refactoring in-place. Today, they want to explore both approaches in depth—having the agent propose specific code changes for each—before deciding which to implement. What's the most effective way to structure this exploration?", "o": {"A": "Resume yesterday's session to explore the first approach, then start a new session for the second, manually recreating the original context.", "B": "Start two fresh sessions, manually providing a summary of yesterday's analysis findings to establish context.", "C": "Resume yesterday's session and explore both approaches sequentially within the same conversation thread.", "D": "Use fork_session to create two branches from yesterday's analysis, exploring one approach in each fork."}, "a": "D", "w": "Why it's correct: D. Correct. Forking from yesterday's session gives each approach its own independent context starting from the same analysis baseline — clean, parallel, no contamination. Option breakdown: • A: Manual recreation is error-prone and loses the exact working state of yesterday's analysis. • B: Redoes work and risks the two sessions diverging from the same baseline you established yesterday. • C: Sequential exploration in one thread lets each approach contaminate the other's context. • D: Correct. Forking from yesterday's session gives each approach its own independent context starting from the same analysis baseline — clean, parallel, no contamination.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-1.7"},
{"id": "ts-5.4-05", "q": "An engineer asks your agent to identify untested code paths in a legacy payment processing module spanning 45 files. After reading the first 8 source files, the agent's responses are becoming noticeably less accurate—it's forgetting previously discussed code patterns and hasn't yet located all test files or traced critical payment flows. What's the most effective approach to complete this investigation?", "o": {"A": "Document all current findings in a summary report, clear context completely, then use that report as the sole reference for continuing the investigation.", "B": "Spawn subagents to investigate specific questions (e.g., \"find all test files for payment processing\", \"trace refund flow dependencies\") while the main agent coordinates findings and preserves high-level understanding.", "C": "Clear context with /clear, then selectively re-read only the most critical files discovered so far, writing key findings to a scratchpad file that persists between context resets.", "D": "Switch to using Grep to search for specific function names instead of reading full files, reducing the content loaded into context for remaining exploration."}, "a": "B", "w": "Why it's correct: B. Correct. Delegate well-scoped investigations to subagents with fresh context, while the main agent keeps the architectural overview. This is the pattern for scaling exploration beyond a single context window. Option breakdown: • A: A single report becomes the only source of truth and tends to compress away the specific code patterns you'd need later. • B: Correct. Delegate well-scoped investigations to subagents with fresh context, while the main agent keeps the architectural overview. This is the pattern for scaling exploration beyond a single context window. • C: Scratchpads help, but clearing + re-reading discards the understanding you already built across 8 files. • D: You can't identify untested paths just by grepping names — you need to read enough of each path to know what branches the tests don't cover.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-5.4-06", "q": "A developer asks the agent to investigate why a specific API endpoint intermittently returns 500 errors. The codebase has 200+ files and the developer doesn't know which components are involved. The agent must trace the error through routing, middleware, business logic, and database layers. What task decomposition approach would be most effective?", "o": {"A": "Have the agent first create a comprehensive plan mapping all code paths through the endpoint before beginning any file exploration or code reading.", "B": "Have the agent dynamically generate investigation subtasks based on what it discovers at each step, adapting its exploration plan as new information about the error path emerges.", "C": "Define a fixed sequence of investigation steps upfront—grep for error patterns, then read error handlers, then check database queries, then examine middleware—executing each step regardless of intermediate findings.", "D": "Run parallel worker agents that simultaneously investigate all four layers, then synthesize their findings to identify where the error originates."}, "a": "B", "w": "Why it's correct: B. Correct. Debugging is adaptive by nature — each file you read changes the most useful next step. Let the agent follow the evidence. Option breakdown: • A: You can't build a correct plan for an unknown error without any exploration. Planning blind wastes time and misses the actual failure path. • B: Correct. Debugging is adaptive by nature — each file you read changes the most useful next step. Let the agent follow the evidence. • C: A fixed pipeline wastes work on layers that aren't involved and can lock the agent out of the actual root cause path. • D: Fan-out is useful once you have well-scoped subtasks. Here, you don't — you'd pay 4× the cost to look in three layers that aren't the problem.", "c": "Workflow Patterns", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-2.1-03", "q": "After adding an MCP server with specialized code refactoring tools (extract_function, rename_variable, inline_function), you notice the agent still uses basic text manipulation via Write and Bash sed commands for refactoring tasks. The MCP server is connected and healthy. Examining the configuration, you find each MCP tool has a minimal description like \"extract_function: extracts a function from code.\" What's the most effective way to improve adoption of the MCP refactoring tools?", "o": {"A": "Implement a request classifier that detects refactoring intent and automatically routes those requests to the MCP server before the agent processes them.", "B": "Remove the Write tool from the agent's configuration for refactoring sessions so it must use the MCP tools for code modifications.", "C": "Accept this as expected behavior since simpler tools like sed are more predictable than specialized refactoring tools.", "D": "Enhance the MCP tool descriptions to explain when each tool is preferable to text manipulation and clarify expected inputs and outputs."}, "a": "D", "w": "Why it's correct: D. Correct. Tool selection is driven by the descriptions Claude sees. When the MCP tools say 'extracts a function from code' and Write/sed come with rich documentation, Claude picks Write/sed. Beef up the descriptions. Option breakdown: • A: A pre-classifier is a separate system to maintain and can misroute. The cheaper fix is to make the tool descriptions strong enough that the agent picks them on its own. • B: Stripping general tools forces adoption by subtraction, and breaks legitimate Write use cases. • C: Capitulating defeats the purpose of integrating refactoring tools. The integration is fine — the descriptions are the problem. • D: Correct. Tool selection is driven by the descriptions Claude sees. When the MCP tools say 'extracts a function from code' and Write/sed come with rich documentation, Claude picks Write/sed. Beef up the descriptions.", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.5-04", "q": "Your agent needs to insert a new helper function into the middle of a 150-line utility module, between two existing functions. The Edit tool fails because its old_string parameter cannot find unique text to match — the file has repetitive docstrings, variable names, and structural patterns. What's the most reliable way to complete this insertion?", "o": {"A": "Use Edit with an extremely long old_string capturing 30+ lines of context to guarantee uniqueness", "B": "Use Edit's replace_all parameter to target a common pattern and embed the new function in the replacement text", "C": "Use Bash to append the function definition to the end of the file using heredoc syntax", "D": "Use Read to load the file, add the function at the appropriate location, then Write the updated file"}, "a": "D", "w": "Why it's correct: D. Correct. When Edit's unique-match contract can't be satisfied in a repetitive file, fall back to Read modify in memory at the intended line Write the full file back. Option breakdown: • A: Long, brittle match strings frequently miss due to whitespace or minor edits and produce confusing failures. • B: replace_all would mutate every occurrence of the pattern — corrupting the whole file. • C: Appending puts the function at the wrong location. The requirement is to insert between two existing functions. • D: Correct. When Edit's unique-match contract can't be satisfied in a repetitive file, fall back to Read modify in memory at the intended line Write the full file back.", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-2.5"},
{"id": "ts-5.4-07", "q": "An engineer who just joined the team asks the agent to help them understand the authentication and authorization architecture before making security improvements. The codebase has 800+ files across multiple services. What exploration strategy will most effectively build understanding, given Claude built-in tools and context limits?", "o": {"A": "Read any CLAUDE.md and README files first, then ask the engineer to specify which 10-15 files are most important for understanding the auth system.", "B": "Launch parallel subagents to explore different services simultaneously, then synthesize their findings into an architectural overview.", "C": "Use Grep to find authentication entry points, read those files, then follow imports and function calls to map the auth flow incrementally.", "D": "Read all files containing \"auth\", \"login\", \"permission\", or \"token\" in their content or filename."}, "a": "C", "w": "Why it's correct: C. Correct. Start at entry points (login, token verify, middleware), then trace outward following real code edges. Incremental, grounded, fits within context limits. Option breakdown: • A: The engineer just joined — they probably don't know which files matter. That's exactly what the agent is supposed to help with. • B: Without knowing where auth lives, fan-out explores too broadly and subagents duplicate and miss cross-service flows. • C: Correct. Start at entry points (login, token verify, middleware), then trace outward following real code edges. Incremental, grounded, fits within context limits. • D: Those keywords hit a huge amount of unrelated code across 800+ files and drown context in noise.", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-5.4-08", "q": "A critical bug is affecting production users. Error logs show exceptions in the OrderProcessing module with a clear stack trace pointing to a specific area, but you haven't worked with this module before. What's the most effective approach?", "o": {"A": "Use plan mode to analyze the error in context of the module's design, enumerate potential root causes, and prioritize fixes systematically.", "B": "Start with direct execution to gather initial information, then switch to plan mode to design a comprehensive solution before implementing.", "C": "Use direct execution to examine the stack trace, read the relevant code, and implement a fix once you identify the root cause.", "D": "Enter plan mode to explore the module's architecture and dependencies before attempting any fix."}, "a": "C", "w": "Why it's correct: C. Debugging is adaptive — each file you read changes the most useful next step, so let the agent follow the evidence. The stack trace already points straight at the failure, so direct execution (read the trace read the relevant code fix once the root cause is identified) is the fastest, most reliable path. Option breakdown: • A: Planning before any exploration of an unknown error is planning blind; it wastes time and easily misses the real failure path. • B: Adding a plan-mode step is unnecessary for an already-localized bug and slows down incident response on a production outage. • C: Correct — direct execution follows the evidence and fixes the bug as soon as the root cause is found. • D: Exploring the whole architecture and dependencies is over-exploration when the stack trace has already pinpointed the location.", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-4.1-01", "q": "After deploying the automated review, you notice high precision but low recall — real bugs are slipping through undetected. Investigation reveals your review prompt instructs Claude to \"only report high- confidence issues you are certain about\" and \"err on the side of not commenting.\" Developers appreciate the low noise, but a race condition that caused a production outage was visible in a reviewed PR and went unreported. You need to substantially improve bug detection while keeping false positive rates manageable for your team. What is the most effective approach?", "o": {"A": "Remove the conservative filtering instructions and prompt Claude to report all potential issues, then apply a programmatic filter to deduplicate and suppress categories that historically generate false positives.", "B": "Add detailed few-shot examples demonstrating bug categories Claude should flag — race conditions, null dereferences, error handling gaps — while keeping the high-confidence filtering instruction to maintain current precision levels.", "C": "Expand the context window by including related test files, recent git history, and the module's dependency graph alongside the diff, giving Claude richer signals to assess issue severity.", "D": "Split the review into a finding stage where Claude's goal is coverage — flagging every potential issue with confidence and severity metadata — and a separate stage that thresholds those findings."}, "a": "D", "w": "Anthropic's code-review guidance for recent Claude models states that \"only report high-confidence\" instructions are followed literally and depress recall, and recommends telling Claude to report every finding with confidence and severity metadata while moving filtering to a separate downstream verification/thresholding stage. Option D is exactly this two-stage coverage-then-threshold pattern; B keeps the recall-killing filter, C doesn't address the filtering instruction, and A's blunt category suppression can re-suppress real bugs and lacks the confidence/severity metadata needed for principled filtering.", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-4.1"},
{"id": "ts-4.5-01", "q": "Your extraction system processes two document types: standard monthly reports (archived after processing) and urgent exception reports (must trigger business alerts within 30 minutes of receipt). Both use the same JSON schema. You want to minimize API costs while meeting latency requirements. How should you architect the processing pipeline?", "o": {"A": "Submit all documents to the real-time Messages API to ensure consistent processing latency across document types.", "B": "Submit all documents to the Batch API with custom_ids for tracking. When results arrive, immediately process urgent documents and trigger delayed alerts for exceptions.", "C": "Queue all documents and submit hourly batches, flagging urgent documents for expedited handling when batch results return.", "D": "Route standard reports to the Batch API for 50% cost savings, and route urgent exception reports to the real-time Messages API."}, "a": "D", "w": "Why it's correct: D. Correct. Match latency profile to document urgency: batch for the bulk (cheap), real-time for the latency-sensitive exceptions (fast). Minimizes cost while meeting SLA. Option breakdown: • A: Consistent but expensive. Standard monthly reports don't need real-time latency and shouldn't pay for it. • B: Batch has up to a 24-hour window — 30-minute alerting SLAs on exception reports can't be met by routing them through batch. • C: Hourly batches still ride the batch SLO and don't guarantee the 30-minute alert window for exceptions. • D: Correct. Match latency profile to document urgency: batch for the bulk (cheap), real-time for the latency-sensitive exceptions (fast). Minimizes cost while meeting SLA.", "c": "Cost & Latency", "dup": "", "conflict": false, "ts": "ts-4.5"},
{"id": "ts-4.2-01", "q": "Your schema includes a skills: string[] field. Production monitoring reveals three consistency issues: (1) compound phrases like \"Python and SQL\" are sometimes kept as one entry, sometimes split; (2) implied but unstated skills occasionally appear in extractions; (3) similar documents produce wildly different array lengths (5-10 vs 40+ entries). Your prompt currently says \"Extract all skills mentioned.\" What's the most effective improvement?", "o": {"A": "Add few-shot examples demonstrating compound phrase handling, explicit mention criteria, and appropriate entry granularity.", "B": "Add constraints: \"Extract 10-20 skills maximum, one skill per entry, only explicitly named skills.\"", "C": "Add post-extraction normalization that maps skills to a canonical taxonomy and deduplicates similar entries.", "D": "Enrich the schema to {skill: string, confidence: float, source_quote: string}[] to capture extraction metadata."}, "a": "A", "w": "Why it's correct: A. Correct. All three issues are about the model's interpretation of what counts as 'a skill.' Few-shot examples teach the pattern concretely — split vs. not-split, mentioned vs. inferred, appropriate granularity. Option breakdown: • A: Correct. All three issues are about the model's interpretation of what counts as 'a skill.' Few-shot examples teach the pattern concretely — split vs. not-split, mentioned vs. inferred, appropriate granularity. • B: Hard count caps are arbitrary and can force the model to drop real skills or invent filler to hit the range. • C: Post-processing can't fix inferred-but-not-mentioned skills or choose the right split for 'Python and SQL' — that decision has to be made at extraction time. • D: Useful signal, but doesn't address the underlying inconsistency in how skills are parsed in the first place.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.2"},
{"id": "ts-5.5-01", "q": "Your system has been operating with 100% human review for 3 months. Analysis shows that extractions with model confidence >90% have 97% accuracy overall. To reduce reviewer workload, you plan to automate high-confidence extractions. Before deploying, what validation step is most critical?", "o": {"A": "Analyze accuracy by document type and field to verify high-confidence extractions perform consistently across all segments, not just in aggregate.", "B": "Compare accuracy at different confidence thresholds (85%, 90%, 95%) to find the optimal cutoff that maximizes automation while minimizing errors.", "C": "Run a two-week pilot routing 25% of high-confidence extractions directly to downstream systems and monitor error reports.", "D": "Verify that 97% accuracy meets requirements for all downstream systems that consume the extracted data."}, "a": "A", "w": "Why it's correct: A. Correct. Aggregate accuracy hides segment failures — one document type could be 70% while others are 99%. Auto-routing by overall number alone risks systemic errors in the weak segments. Option breakdown: • A: Correct. Aggregate accuracy hides segment failures — one document type could be 70% while others are 99%. Auto-routing by overall number alone risks systemic errors in the weak segments. • B: Threshold tuning is worth doing, but only after you know the accuracy holds uniformly across segments — otherwise you're optimizing a number that lies. • C: A pilot is good practice, but it's downstream of the segment analysis — if a segment is systematically wrong, you'll learn it by harming users. • D: An important product question, but it assumes the 97% holds everywhere — again, that's what segment analysis verifies first.", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-5.5"},
{"id": "ts-4.3-01", "q": "Your extraction pipeline processes contracts that frequently include amendments. When a contract contains both original terms and later amendments (e.g., original clause specifies \"30-day payment terms\" while Amendment 1 changes this to \"45 days\"), the model inconsistently extracts one value or the other with no indication of which applies. What's the most effective approach to improve extraction accuracy for documents with amendments?", "o": {"A": "Redesign the schema so amended fields capture multiple values, each with source location and effective date.", "B": "Add prompt instructions to always extract the most recent amendment value and ignore superseded original terms.", "C": "Preprocess documents with a classifier that identifies and removes superseded sections before the main extraction step.", "D": "Implement post-extraction validation using pattern matching to detect amendments and flag those extractions for manual review."}, "a": "A", "w": "Why it's correct: A. Correct. Amendments are structurally about versioned values. A schema with value + source location + effective date models the domain correctly and stops forcing the model to pick one. Option breakdown: • A: Correct. Amendments are structurally about versioned values. A schema with value + source location + effective date models the domain correctly and stops forcing the model to pick one. • B: Downstream consumers sometimes need the original too (e.g., for dispute resolution). Hard-coding 'most recent wins' throws that away. • C: Deleting sections with a classifier can accidentally strip content that's still legally effective — amendments often modify subsets of clauses. • D: Routes every amended contract to a human — expensive, and still doesn't give downstream systems a structured answer.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.3"},
{"id": "ts-4.4-01", "q": "Your extraction system implements automatic retries when validation fails. On each retry, the specific validation error is appended to the prompt. This retry-with-error-feedback approach resolves most failures within 2-3 attempts. For which failure pattern would additional retries be LEAST effective?", "o": {"A": "The model extracts keywords as a nested object organized by category when the schema requires a flat array of strings", "B": "The model extracts citation counts as locale-formatted strings (\"1,234\") when the schema requires integers", "C": "The model extracts dates as ISO 8601 datetime strings (\"2023-03-15T00:00:00Z\") when the schema requires only the date portion (YYYY-MM-DD)", "D": "The model extracts \"et al.\" for co-authors when the full list exists only in an external document not in the input"}, "a": "D", "w": "Why it's correct: D. Correct. No amount of retrying teaches the model information that isn't in the input. Retry-with-error-feedback only fixes mistakes the model could have gotten right from the source. Option breakdown: • A: A structural mismatch the model can definitely correct given feedback about the expected shape. • B: The required number is present in the document — the model just needs to stop formatting it. Easy for feedback-retry to fix. • C: Pure formatting fix — the underlying value is correct and the model can trim the time portion on retry. • D: Correct. No amount of retrying teaches the model information that isn't in the input. Retry-with-error-feedback only fixes mistakes the model could have gotten right from the source.", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-4.4"},
{"id": "ts-4.2-02", "q": "Your extraction pipeline processes restaurant menus and must output structured JSON with fields for item names, descriptions, prices, and dietary tags. Some menus use inconsistent formatting—prices as \"$12\" vs \"12.00\", dietary info as icons vs text. What's the most reliable approach?", "o": {"A": "Use separate extraction calls for each field to ensure consistent handling of each type.", "B": "Extract data as-is and normalize formats in post-processing code after Claude returns.", "C": "Request multiple extraction attempts per document and select the most common format.", "D": "Define a strict output schema and include format normalization rules in your prompt."}, "a": "D", "w": "Why it's correct: D. Correct. Strict schema + explicit normalization rules ('prices as decimal with two places', 'dietary as enumerated tags') lets the model both extract and normalize in one pass. Option breakdown: • A: Multiple calls per menu multiplies cost and latency and loses cross-field context (e.g., which dietary icons sit next to which item). • B: Post-processing a raw blob is brittle — deterministic code has to handle every format permutation. Better to let the model normalize at extraction time. • C: Ensemble voting is expensive and can still pick a wrong-format majority. • D: Correct. Strict schema + explicit normalization rules ('prices as decimal with two places', 'dietary as enumerated tags') lets the model both extract and normalize in one pass.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.2"},
{"id": "ts-4.1-02", "q": "Your system extracts event metadata (date, location, organizer, attendee_count) from news articles using a JSON schema with all nullable fields. During evaluation, you observe the model frequently generates plausible but incorrect values for fields not mentioned in the article—for example, outputting \"500\" for attendee_count when the source contains no attendance information. What's the most effective way to reduce these false extractions?", "o": {"A": "Add a post-processing step using a second LLM call to verify each extracted value exists in the source document.", "B": "Add prompt instructions to return null for any field where information is not directly stated in the source.", "C": "Make all schema fields required (non-nullable) with strict validation rules to ensure the model only outputs verifiable data.", "D": "Upgrade to a more capable model tier with improved instruction-following to reduce hallucination tendencies."}, "a": "B", "w": "Why it's correct: B. Correct. The fields are already nullable; the model just needs an explicit instruction to prefer null over a plausible guess. This is the standard fix for schema-aware hallucination. Option breakdown: • A: Expensive second pass for a behavior you can correct at the source — tell the model to return null when the field isn't stated. • B: Correct. The fields are already nullable; the model just needs an explicit instruction to prefer null over a plausible guess. This is the standard fix for schema-aware hallucination. • C: Required fields force the model to invent values when information is missing — the opposite of what you want. • D: Adds cost and still doesn't tell the model your policy — returning null instead of inventing.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.1"},
{"id": "ts-4.4-02", "q": "After implementing tool use with strict schema definitions, JSON syntax errors are eliminated, but 5% of extractions still have valid JSON with empty arrays or null values for required fields like citations and methodology. Spot-checking reveals that source documents contain this information, but in varied formats—inline citations vs. bibliographies, methodology sections vs. details embedded in introductions. What's the most effective way to address these failures?", "o": {"A": "Implement retry logic that re-sends requests when validation detects empty required fields.", "B": "Build a regex-based post-processing layer that scans source documents for citation patterns and methodology keywords, populating empty fields when the model fails to extract.", "C": "Modify your schema to make citations and methodology optional, and flag incomplete records for manual review rather than failing validation.", "D": "Add few-shot examples demonstrating extractions from documents with varied structures—showing how to identify citations in different formats and locate methodology details across section types."}, "a": "D", "w": "Why it's correct: D. Correct. The failure mode is the model not recognizing varied formats. Concrete examples across the format distribution directly raise recall on the 5%. Option breakdown: • A: Retry on the same prompt won't suddenly teach the model to recognize methodology embedded in an intro. The extraction capability is the gap. • B: Regex over prose is brittle, misses the nuanced cases (intro-embedded methodology), and ships silently wrong data. • C: Papers over the symptom. The fields really are required downstream — routing them to humans trades one problem for reviewer workload. • D: Correct. The failure mode is the model not recognizing varied formats. Concrete examples across the format distribution directly raise recall on the 5%.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.4"},
{"id": "ts-4.4-03", "q": "Your extraction pipeline processes invoices and extracts line items, subtotals, tax amounts, and grand totals. During evaluation, you discover that in 18% of extractions, the sum of extracted line item amounts doesn't match the extracted grand total—sometimes due to OCR errors in the source document, sometimes due to extraction mistakes by the model. Downstream accounting systems reject records with mismatched totals. What's the most effective approach to improve extraction reliability?", "o": {"A": "Add a \"calculated_total\" field where the model sums extracted line items alongside a \"stated_total\" field. Flag records for human review when values differ.", "B": "Extract line items and totals independently, then use a separate validation model to reconcile discrepancies by determining which extracted values are most likely correct.", "C": "Add few-shot examples demonstrating invoices where extracted line items sum correctly to the stated total, encouraging the model to produce mathematically consistent extractions.", "D": "Implement post-processing that automatically adjusts line item amounts proportionally when their sum doesn't match the stated total."}, "a": "A", "w": "Why it's correct: A. Correct. Capturing both values makes the discrepancy a first-class signal — you catch OCR errors and extraction mistakes uniformly, and you can route only the mismatched 18% to humans. Option breakdown: • A: Correct. Capturing both values makes the discrepancy a first-class signal — you catch OCR errors and extraction mistakes uniformly, and you can route only the mismatched 18% to humans. • B: A reconciliation model can mask OCR errors by silently picking one number over another — the accounting system still gets wrong data without a flag. • C: Can nudge the model toward consistency, but when the source itself is internally inconsistent (OCR errors), the model has to choose one 'wrong'. • D: Silent financial data rewrites are dangerous — you'd be fabricating line items for a downstream accounting system.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.4"},
{"id": "ts-4.3-02", "q": "Your pipeline uses a tool called extract_metadata with a JSON schema for paper details. You've also defined lookup_citations and verify_doi tools for enrichment. During testing, you notice that when users include requests like \"extract the metadata and tell me how cited it is,\" Claude sometimes calls lookup_citations first, which fails because it needs the DOI that extract_metadata would provide. What's the most effective way to ensure structured metadata extraction happens first?", "o": {"A": "Set tool_choice to \"any\" so Claude must use a tool, combined with system prompt instructions prioritizing extract_metadata.", "B": "Set tool_choice to \"auto\" and reorder the tool definitions so extract_metadata appears first in the tools array, since Claude prioritizes earlier-listed tools.", "C": "Set tool_choice to {\"type\": \"tool\", \"name\": \"extract_metadata\"} and process the enrichment requests in subsequent turns after receiving the extracted metadata.", "D": "Set tool_choice to {\"type\": \"tool\", \"name\": \"extract_metadata\"} for every API call in the pipeline, ensuring Claude always extracts metadata before any enrichment can occur."}, "a": "C", "w": "Why it's correct: C. Correct. tool_choice=specific-tool deterministically forces extract_metadata on the first turn. Then you hand control back to 'auto' to let the model use citations/DOI enrichment with the metadata in context. Option breakdown: • A: 'any' forces a tool call but doesn't force the right one. You'd still see lookup_citations picked first. • B: There's no documented ordering preference to rely on; this assumes behavior that isn't contractual. • C: Correct. tool_choice=specific-tool deterministically forces extract_metadata on the first turn. Then you hand control back to 'auto' to let the model use citations/DOI enrichment with the metadata in context. • D: Pinning extract_metadata on every call prevents the enrichment tools from ever being used.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.3"},
{"id": "ts-4.3-03", "q": "Your extraction uses tool use with a JSON schema where property_type is defined as an enum: ['house', 'apartment', 'condo', 'townhouse']. After deployment, 8% of extractions fail schema validation. Investigation reveals listings mention many uncommon property types—\"studio\", \"loft\", \"duplex\", \"mobile home\", \"tiny house\", \"converted warehouse\"—and new types continue appearing regularly. What's the most effective long-term solution?", "o": {"A": "Continuously expand the enum to include newly observed property types and add monitoring for additional edge cases.", "B": "Add an \"other\" value to your enum with a separate property_type_detail string field for specifics when \"other\" is selected.", "C": "Change property_type from an enum to a free-form string and implement a normalization step in post-processing.", "D": "Add few-shot examples to your prompt demonstrating how to map unexpected property types to the closest existing enum value."}, "a": "B", "w": "Why it's correct: B. Correct. Keeps the strong enum for the common cases (clean downstream joins) while giving a well-typed escape hatch that preserves detail. Stable long-term. Option breakdown: • A: Whack-a-mole enum maintenance — every new listing style risks another validation failure. • B: Correct. Keeps the strong enum for the common cases (clean downstream joins) while giving a well-typed escape hatch that preserves detail. Stable long-term. • C: Loses the validation guarantee entirely and pushes the normalization problem downstream with no canonical vocabulary. • D: Forcing 'tiny house' into 'house' drops real distinctions downstream — you're silently lossy.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.3"},
{"id": "ts-4.2-03", "q": "Your extraction system parses e-commerce product descriptions to extract specifications like dimensions, weight, and materials into JSON. Despite having a well-defined schema, the model inconsistently extracts the \"materials\" field—sometimes returning \"cotton blend\", other times \"Cotton/Polyester mix\", and occasionally omitting the field when material information is clearly present in the source. What's the most effective way to improve extraction consistency?", "o": {"A": "Make the \"materials\" field required instead of optional in the schema to force the model to always extract a value", "B": "Switch to a more capable model tier since inconsistent extraction indicates insufficient model capability", "C": "Set temperature to 0 to eliminate randomness and ensure deterministic outputs", "D": "Add few-shot examples showing 2-3 complete input-output pairs with standardized material description formats"}, "a": "D", "w": "Why it's correct: D. Correct. Few-shot examples demonstrate the exact canonical format you want ('cotton/polyester' as a normalized list), and they also raise recall on material info that was being skipped. Option breakdown: • A: Required-ness doesn't solve format inconsistency, and it can force invented values when material info is genuinely missing. • B: Costly, and doesn't address the actual cause — the model doesn't know the canonical output format you want. • C: Determinism doesn't define the right format; it just makes the wrong-format answers consistent. • D: Correct. Few-shot examples demonstrate the exact canonical format you want ('cotton/polyester' as a normalized list), and they also raise recall on material info that was being skipped.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.2"},
{"id": "ts-5.5-02", "q": "After deployment, you find that 12% of extractions contain semantic errors that pass JSON schema validation (e.g., a duration like \"30 minutes\" incorrectly placed in an ingredient quantity field). Human reviewers have capacity to check only 20% of extractions. Which approach most effectively allocates reviewer attention?", "o": {"A": "Have the model output field-level confidence scores, then calibrate review thresholds using a labeled validation set.", "B": "Randomly sample 20% of extractions for review, using corrections to track accuracy and identify error patterns.", "C": "Prioritize review of all extractions where required fields are empty or explicitly marked as not found.", "D": "Review all extractions from documents with formatting anomalies such as unusual layouts or mixed content types."}, "a": "A", "w": "Why it's correct: A. Correct. Field-level confidence lets you route the low-confidence 20% — which is where the 12% semantic errors concentrate — to humans. Calibration makes the threshold choice data-driven. Option breakdown: • A: Correct. Field-level confidence lets you route the low-confidence 20% — which is where the 12% semantic errors concentrate — to humans. Calibration makes the threshold choice data-driven. • B: Great for measurement, poor for coverage — random sampling only catches 20% of the 12% errors (~2.4% total). Confidence-based routing finds far more. • C: Empty fields are a narrow error mode. The 12% problem is wrong values in populated fields, which this filter misses. • D: A useful heuristic, but formatting anomaly doesn't reliably predict where fields got confused with each other.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-5.5"},
{"id": "ts-4.5-02", "q": "Your CI pipeline performs security-focused code reviews on approximately 50 PRs daily, currently costing $150/day using the synchronous API. Reviews are non-blocking—developers merge after tests pass and address findings in follow-up commits. You're evaluating the Message Batches API for its 50% cost reduction. What factor most determines whether batch processing is appropriate for this use case?", "o": {"A": "Whether you can structure each review as a single request without multi-turn refinement.", "B": "Whether reducing per-review latency from 30-60 seconds to near-instant matters for your workflow.", "C": "Whether review feedback arriving up to 24 hours after PR creation remains actionable.", "D": "Whether your result processing can handle reviews arriving in a different order than submitted."}, "a": "C", "w": "The Message Batches API is asynchronous — most batches finish within 1 hour but can take up to 24 hours — so the decisive suitability factor is latency tolerance: whether review findings delivered up to 24 hours after PR creation are still actionable in a non-blocking, merge-then-fix workflow. Batching increases latency (B is backwards), results are correlated via custom_id so ordering is a non-issue (D), and single-request structuring (A) is secondary to the latency question.", "c": "Cost & Latency", "dup": "", "conflict": false, "ts": "ts-4.5"},
{"id": "ts-4.5-03", "q": "Documents arrive continuously throughout business hours and need structured data extracted. To reduce costs, you want to use the Message Batches API (50% discount, up-to-24-hour processing window). Your SLA specifies that extraction results must be available within 30 hours of document arrival with 99.9% reliability. Which batching strategy is most appropriate?", "o": {"A": "Submit batches every 6 hours containing documents from that window", "B": "Submit a single batch at end of day containing all documents from that day", "C": "Submit batches every 4 hours containing documents from that window", "D": "Use the real-time API for all documents instead of batch processing"}, "a": "C", "w": "Why it's correct: C. Correct. Max 4-hour wait + up to 24-hour batch SLO = 28-hour worst case, leaving a 2-hour cushion under the 30-hour SLA to absorb batch variance and hit 99.9%. Option breakdown: • A: Worst-case a document waits 6 hours to be batched and then up to 24 hours to process = 30 hours exactly. No safety margin for a 99.9% reliability target. • B: A doc arriving just after morning startup waits all day to be batched plus up to 24 hours to process — well over 30 hours. • C: Correct. Max 4-hour wait + up to 24-hour batch SLO = 28-hour worst case, leaving a 2-hour cushion under the 30-hour SLA to absorb batch variance and hit 99.9%. • D: Meets SLA trivially but throws away the 50% cost saving the question asks you to capture.", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.5"},
{"id": "ts-4.5-04", "q": "After your daily batch of 10,000 documents completes, 300 documents (3%) failed with \"context_length_exceeded\" errors. The results file identifies each failure by custom_id. What's the most cost-effective approach to process these failures?", "o": {"A": "Reprocess the entire batch with prompt caching enabled to reduce the cost of retrying requests with identical system prompts", "B": "Resubmit only the 300 failed documents after chunking them into smaller pieces, then combine the partial extractions", "C": "Resubmit the entire 10,000 document batch using a model tier with a larger context window", "D": "Increase the max_tokens parameter for the 300 failed documents and resubmit them in a new batch"}, "a": "B", "w": "Why it's correct: B. Correct. Targeted, and it addresses the actual cause (input too long). Chunk the oversized docs, extract per chunk, then merge — minimum tokens, fixes the specific failure mode. Option breakdown: • A: Re-running 10,000 successful documents to solve 300 failures is wasteful regardless of caching savings. And caching doesn't fix the length-exceeded error. • B: Correct. Targeted, and it addresses the actual cause (input too long). Chunk the oversized docs, extract per chunk, then merge — minimum tokens, fixes the specific failure mode. • C: Expensive (reprocessing 9,700 successes) and may still fail on truly outsized documents. • D: max_tokens controls output length, not input length. It doesn't solve context_length_exceeded, which is about the combined input-plus-output budget.", "c": "Cost & Latency", "dup": "", "conflict": false, "ts": "ts-4.5"},
{"id": "ts-1.4-03", "q": "The synthesis agent completes its initial pass but flags that three key research questions remain unanswered because the web search and document analysis agents didn't find relevant information on those specific subtopics. The coordinator currently proceeds directly to report generation, producing reports with incomplete coverage. What change would most effectively improve research completeness?", "o": {"A": "Have the coordinator evaluate synthesis output for gaps, then re-delegate to web search and document analysis with targeted queries before Invoking synthesis again.", "B": "Increase the initial breadth of queries sent to web search and document analysis to reduce the probability of missing relevant information.", "C": "Have the report generation agent note which research questions couldn't be answered, so users understand the limitations of the final output.", "D": "Give the synthesis agent direct access to web search tools so it can autonomously fill knowledge gaps without returning control to the coordinator."}, "a": "A", "w": "", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.4"},
{"id": "ts-2.1-04", "q": "Your search products tool queries an external catalog API that returns paginated results (50 items per request). Production logs show queries frequently match 200+ products, and the design that auto-fetches all pages causes 15-20 second delays. How should you redesign the pagination handling?", "o": {"A": "Create separate search products and fetch more results tools for pagination.", "B": "Implement server-side relevance ranking and return only the top 50 most relevant items.", "C": "Add a max pages parameter (default: 2) that controls how many pages are fetched internally.", "D": "Return the first page with total match count and cursor for additional pages."}, "a": "D", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.2-05", "q": "Your search Flights tool calls an external airline API that occasionally returns a 503 Service Unavailable error. What is the most effective way to handle this error in your tool implementation?", "o": {"A": "Return an empty flight list as if the search succeeded but found no matching flights.", "B": "Log the error internally and return an empty response, letting the model continue without the flight data.", "C": "Return an error message in the tool result explaining the service is temporarily unavailable.", "D": "Automatically retry the request up to five times with exponential backoff before returning results to the agent."}, "a": "D", "w": "", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-2.2-06", "q": "Your MCP server implements a check_availability tool that queries an external calendar API. During testing, you encounter three error conditions: (1) the tool is called with a malformed request, missing the required user_email parameter (2) the calendar API returns a 404 because the specified user doesn't exist in the calendar system (3) the calendar API returns a 503 because the service is temporarily unavailable. How should each error be reported according to MCP's error handling design?", "o": {"A": "Report all three as tool results with isError: true", "B": "Report errors 1 and 2 as JSON-RPC protocol errors, report error 3 as a tool result with isError: true", "C": "Report error 1 as a JSON-RPC protocol error, report errors 2 and 3 as tool results with isError: true", "D": "Report all three as JSON-RPC protocol errors."}, "a": "C", "w": "", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-2.1-05", "q": "Your documents (query) tool returns results as \"Found 3 documents: Q2 Budget Proposal, Q2 Budget Forecast, Annual Review\". You want the agent to document (4, multi) and doc (24, multi). What return format would best enable these multi-step workflows?", "o": {"A": "URLs that users can click to open the document in their browser.", "B": "Structured data containing document IDs and metadata for each result.", "C": "A JSON array of document titles extracted from the search results.", "D": "More detailed human-readable descriptions including the size and authors."}, "a": "B", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.3-02", "q": "Your agent has access to 50+ specialized API connectors for different external services. As the connector library grew, tool selection accuracy dropped to 58%. You design a search_connectors(description) tool that finds matching connectors, but in testing agents frequently skip searching and call connectors directly (often incorrectly), or search select wrong connectors from the filtered results. How should you design the tool composition pattern to address both issues?", "o": {"A": "Design connectors with built-in compatibility validation that return descriptive errors for mismatched requests.", "B": "Design a find_and_execute(description, params) composite tool that searches and immediately executes the best matching connector.", "C": "Enhance all connector descriptions with detailed usage samples, edge cases, and input requirements. Add few-shot examples showing the correct search-then-use workflow.", "D": "Design search_connectors to dynamically add matched connectors to the agent's available tools. Connectors start unavailable and persist once discovered."}, "a": "D", "w": "", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.3"},
{"id": "ts-2.2-07", "q": "Your publish article tool calls an external CMS API that occasionally returns transient errors (network timeouts, 503s) and non-transient errors (403 permission denied, 422 validation failure). Currently, every error is returned directly to the agent, which leads to the agent retrying non-transient errors and wasting turns on failures that will never succeed. How should you partition error-handling responsibility between the tool implementation and the agent?", "o": {"A": "Handle all errors inside the tool: Implement retries with exponential backoff for every error type, and only surface a failure to the agent after a fixed number of retry attempts have been exhausted.", "B": "Handle transient errors (timeouts, 503s) with automatic retries inside the tool implementation, and surface non-transient errors (permission denied, validation fallures) to the agent with descriptive messages so it can take corrective action.", "C": "Surface all errors to the agent immediately with detailed context, and let the agent decide which errors to retry and how many times-keeping the tool implementation stateless and simple.", "D": "Implement a universal error handler that catches all exceptions and returns a generic \"tool unavailable- try again later\" message, shielding the agent from error complexity."}, "a": "B", "w": "", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-1.5-02", "q": "Your remove_team_member tool uses a dry_run: boolean parameter for previewing impacts before execution. Production monitoring shows the agent bypasses the preview step in 15% of calls by calling with dry_run=false directly. You need to ensure every removal is preceded by a preview that the user explicitly confirms. What is the most reliable approach?", "o": {"A": "Add server-side validation that permits dry_run=false only when a dry_run=true call with identical parameters occurred within the past 60 seconds.", "B": "Replace with two tools: preview_remove_member returns impact details and a single-use confirmation token; execute_remove_member requires that token, binding execution to the specific previewed action.", "C": "Annotate the tool as requiring confirmation and configure the orchestration layer to prompt the user for approval before forwarding any calls to annotated tools.", "D": "Add detailed instructions and few-shot examples to the tool description requiring the agent to always call with dry_run=true first and wait for user confirmation before calling with dry_run=false."}, "a": "B", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-1.5"},
{"id": "ts-1.5-03", "q": "Your expense reimbursement agent processes employee requests using a process reimbursement tool. Company policy requires that reimbursements above $500 must be approved before funds are disbursed. The agent handles hundreds of requests daily, and you need the threshold enforcement to be tamper-proof regardless of how the agent is prompted ensures the $500 approval threshold cannot be bypassed?", "o": {"A": "The process reimbursement tool accepts an approved by manager parameter. The system prompt instructs the agent to only set this to true after confirming that a manager approved the request. A nightly audit script reviews all reimbursements where approved by manager was set to true.", "B": "Provide two tools: auto reimburse (hard-coded limit of $500) and manager approval. Include detailed system prompt instructions telling the agent to check the amount and use the appropriate tool. Add a Post ToolUse hook that logs which tool was called for auditing.", "C": "The process reimbursement tool accepts amount and details, and internally enforces the threshold; amounts <$500 are auto-disbursed and the tool returns a success confirmation. Amounts >$500 cause the tool to create a pending approval request and return a status indicating manager review is pending.", "D": "Implement the threshold check in a PreToolUse hook that inspects the amount parameter before process reimbursement executes. If the amount exceeds $500, the hook modifies the context to add a requires approval: true flag, which the tool checks before disbursing."}, "a": "C", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-1.5"},
{"id": "ts-2.1-06", "q": "Your order management system requires tools for three distinct operations: issuing refunds (requires amount and reason), canceling orders (requires reason), and res (requires shipping address). Each operation shares an order id parameter but has different additional requirements. You notice during testing that with your current frequently omits required parameters or includes irrelevant ones. What design change will most effectively improve parameter accuracy?", "o": {"A": "Split into three separate tools (each defining only the parameters required for that specific operation.", "B": "Keep one unified tool with all parameters marked optional, but add few-shot examples in the system prompt showing correct parameter combinations for each operation.", "C": "Keep one unified tool but add JSON Schema if-then-else conditionals to enforce that parameters like amount are required only when the operation type is \"refund\".", "D": "Keep one unified tool with a nested operation object parameter whose internal structure varies by operation type, documented in the tool description."}, "a": "A", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.1-07", "q": "Your portfolio value tool returns the total value of a user's investment portfolio. You're deciding between returning a structured JSON object with explicit fields versus returning information as a formatted text string. What is the primary advantage of using structured output with defined fields?", "o": {"A": "Structured JSON consumes significantly fewer tokens than natural language, substantially reducing API costs.", "B": "The agent can reliably extract specific values without parsing free form text, reducing errors in subsequent operations.", "C": "Structured JSON is processed deterministically by the model, significantly improving accuracy when extracting values.", "D": "JSON schemas automatically validate that the underlying API returned correct data before the agent processes it."}, "a": "B", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.2-08", "q": "Your scheduling agent uses get_available_slots(date, provider_id) to retrieve open appointment times, then book_appointment(provider_id, slot_time, patient_id) to reserve a slot. tickets show that 15% of booking attempts fall with \"slot no longer available\" because another user booked the slot between the availability check and the booking call. How should you r these tools?", "o": {"A": "Modify book_appointment to return detailed failure information including currently available alternative slots when the requested slot is unavailable, enabling the agent to retry with a di time.", "B": "Keep both tools but add retry logic to the agent's system prompt, instructing it to call get_available_slots again and select a different time if booking fails.", "C": "Add a hold_slot(provider_id, slot_time) tool that creates a 60 second temporary reservation, requiring the agent to call it between checking availability and booking.", "D": "Combine both tools into a single find_and_book_appointment that atomically checks availability and books, returning either the confirmed booking or available alternatives."}, "a": "D", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-2.1-08", "q": "Your agent has a log_workout tool that accepts exercise_type (string), value (number), and measurement (string). Production monitoring shows the agent frequently passes mismatched combinations-using measurement: \"reps\" for cardio exercises like running, or measurement: \"miles\" for strength exercises like bench press. Your exercises naturally divide into two categories: cardio (measured in time or distance) and strength (measured in reps and sets). 23% of tool calls have invalid combinations. What approach would most effectively reduce these errors?", "o": {"A": "Implement server-side validation returning descriptive errors for invalid combinations, allowing the agent to retry with corrections.", "B": "Add enum constraints on measurement limiting values to \"minutes\", \"miles\", \"reps\", or \"sets\" to prevent arbitrary measurement strings.", "C": "Add explicit examples to the tool description showing valid combinations (e.g., \"For running: use minutes or miles. For push-ups: use reps\") with constraints for each exercise category.", "D": "Split into log_cardio_workout (with duration_minutes or distance_miles parameters) and log_strength_workout (with reps and sets parameters)."}, "a": "D", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.1-09", "q": "Your MCP server includes archive_file(file_id) and delete_file(file_id) tools. Production logs show the agent calls delete_file when users ask to \"remove old backups,\" policy requires archiving backup files. Both tools currently have minimal descriptions: \"Archives a file\" and \"Deletes a file.\" Which change most directly improves tool selection?", "o": {"A": "Add a confirmation step that requires users to type \"CONFIRM DELETE\" before delete_file executes.", "B": "Implement server-side validation that rejects delete_file calls for files tagged as backups, returning an error message suggesting archive_file.", "C": "Expand tool descriptions to clarify use cases, adding guidance like \"Do not use for backup files\" to delete_file.", "D": "Add few-shot examples to the system prompt demonstrating that requests involving \"backup\" or \"old\" should use archive_file."}, "a": "C", "w": "", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.1-10", "q": "Your CRM agent's delete_contact tool handles requests like \"delete the duplicate entry for Acme Corp.\" The database contains similarly named records (e.g., \"Acme Corp,\" \"Acme Corporation,\" \"ACME Corp Inc.\"), and analytics show 8% of deletions are reversed within 24 hours due to misidentified records. Users have also complained that the current multi-step confirmation flow adds too much friction to routine cleanup tasks. Which approach most effectively reduces the error rate while maintaining workflow efficiency?", "o": {"A": "Present matched records with differentiating fields and require single-click confirmation of the intended target before executing deletion.", "B": "Require users to supply the exact record ID from the CRM Interface rather than using natural language references to contact names.", "C": "Deploy automated duplicate detection that identifies and merges probable duplicates, removing the need for manual deletion requests.", "D": "Implement soft-delete with a 30-day recovery window so users can undo mistakes without slowing down the deletion workflow."}, "a": "A", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-4.4-04", "q": "Your invoice extraction uses tool use with strict JSON schemas. JSON syntax errors never occur, but 12% of extractions fail semantic validation--for example, line Item amounts don't extracted total, or vendor IDs don't match valid formats. These failures currently route to manual review. What's the most effective approach to reduce manual review volume while m accuracy?", "o": {"A": "Retry the extraction up to 3 times when validation fallis, accepting the first result that passes validation.", "B": "Implement post-processing logic that automatically corrects common amors, such as recalculating totais from line items when sums don't match.", "C": "When validation falls, make a follow-up request with the document, extraction, and validation errors for model correction.", "D": "Add stricter schema constraints with detailed field descriptions to prevent the model from generating invalid values initially."}, "a": "C", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.4"},
{"id": "ts-4.5-05", "q": "Your team is extracting structured data from 50,000 legacy legal contracts under a two-week deadline. Initial testing with 500 sample documents shows 82% pass JSON schema first attempt, while the remaining 18% fall due to diverse issues—missing required fields, malformed dates, and incorrectly identified parties. Documents that fail typically need refinements targeting their specific failure modes before extraction succeeds. Which batch processing strategy is the most cost-efficient while still meeting the deadline?", "o": {"A": "Split documents into 10 sequential batches of 5,000 each, analysing results and refining prompts between batches to improve extraction quality progressively.", "B": "Submit all 50,000 documents via batch API, then submit failed extractions in successive batches— refining prompts between each batch—until all documents pass validation.", "C": "Use the real-time API for all 50,000 documents since the batch API's 24-hour processing window creates unacceptable deadline risk.", "D": "Process 2,000 sample documents via real time API to identify failure patterns and refine prompts, then batch process all 50,000 with the optimized prompts."}, "a": "B", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.5"},
{"id": "ts-4.3-04", "q": "Your system must extract event details from calendar invitations and output JSON that strictly conforms to a schema with fields for title, date, time, location, and attendees. Downstream reject any malformed or non- conformant JSON. What approach provides the most reliable schema compliance?", "o": {"A": "Define a tool with your target schema as input parameters and have Claude call it with the extracted data.", "B": "Pre-fill Claude's response with an opening brace to force JSON output, then complete and parse the response.", "C": "Append instructions like \"Output only valid JSON matching the schema exactly\" and implement retry logic to re-prompt when JSON parsing fails.", "D": "Include detailed JSON formatting instructions and the target schema in your prompt, then parse Claude's text response as JSON."}, "a": "A", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.3"},
{"id": "ts-5.4-09", "q": "Your extraction system uses tool_use with a JSON schema containing 12 fields and detailed descriptions, totaling approximately 2,500 tokens for the complete tool definition. Processing documents under 150K tokens yields 98% accuracy. For documents between 175-190K tokens, accuracy drops to 71%, with information from the final third consistently missed. The model's context window is 200K tokens. What is the most likely cause?", "o": {"A": "Tool definitions consume input context tokens. Combined with system prompts and document content, the total approaches the context limit, degrading end-of-document processing.", "B": "Very long documents exceed the model's effective attention span regardless of context limits, causing accuracy degradation for content farther from the prompt instructions.", "C": "The model distributes attention proportionally across input length, causing fields mentioned only once near the document's end to receive insufficient processing focus.", "D": "Schemas exceeding 8-10 fields increase decision complexity during parameter generation, reducing extraction accuracy independent of document length."}, "a": "A", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-4.3-05", "q": "The extraction pipeline receives documents of varying types—some are invoices, others are contracts, and some are receipts. You've defined separate extraction tools, each with its own schema tailored to the document type. During testing, you observe that with tool_choice: \"auto\", Claude sometimes returns conversational text instead of calling an extraction tool, causing downstream parsing failures. You need guaranteed structured output without knowing the document type in advance. What's the most effective approach?", "o": {"A": "Consolidate all document types into a single unified-schema extraction tool and force that tool.", "B": "Keep tool_choice: \"auto\" with system prompt instructions requiring tool use.", "C": "Set tool_choice: \"any\" with all extraction tools defined.", "D": "Add a preliminary classification call, then make a second call with tool_choice forced to the identified extraction tool."}, "a": "C", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.3"},
{"id": "ts-4.4-05", "q": "Monitoring shows 12% of extractions fall Pydantic validation with specific errors like \"expected float for quantity, got '2 to 3\". Retrying these requests without modification produces failures. What's the most effective approach to recover from these validation failures?", "o": {"A": "Set temperature to 0 to eliminate output variability and ensure consistent formatting", "B": "Send a follow-up request including the validation error, asking the model to correct its output", "C": "Pre-process source documents to standardize problematic formats before sending them for extraction", "D": "Implement a secondary pipeline using a larger model tier to reprocess documents that fail validation"}, "a": "B", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.4"},
{"id": "ts-5.1-05", "q": "After three months of weekly sessions, your conversation history has grown to 85,000 tokens. When users ask \"What did we conclude about the theme of isolation?\", the assistant provides generic literary analysis rather than referencing the group's specific insights from earlier sessions. Discussions often build on previous meetings' conclusions, so maintaining narrative context is important. What's the most effective approach?", "o": {"A": "Add structured XML tags to mark significant discussion conclusions throughout the conversation history.", "B": "Use semantic embedding to index the full conversation history and retrieve only relevant past exchanges for each user query, replacing the linear conversation format with retrieved segments.", "C": "Implement rolling window truncation to keep only the most recent 25,000 tokens.", "D": "Implement progressive summarization where older conversation blocks are replaced with concise summaries that explicitly extract key conclusions, decisions, and recurring themes, keeping recent exchanges verbatim."}, "a": "D", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-06", "q": "After a 40-minute session helping plan a dinner party, the conversation has grown to 78,000 tokens. The history includes: (1) the user mentioning a guest has a severe shellfish allergy, (2) measurements for scaling recipes to 8 servings, (3) the user's clarification that \"room temperature butter\" means 68°F in their kitchen, and (4) general back-and-forth about meal timing and presentation. You need to implement context management before the window limit is reached. What approach best balances information preservation with token reduction?", "o": {"A": "Summarize the entire conversation history into a concise summary capturing main topics discussed, then append new messages going forward.", "B": "Implement a sliding window retaining only the most recent 20,000 tokens relying on users to re-state important information when relevant.", "C": "Store the full conversation externally and use semantic search to retrieve relevant portions for each turn, loading only matching segments into context.", "D": "Extract critical structured data (allergies, serving counts, user-defined terms) into a compact reference section, summarize general discussion, and retain recent exchanges verbatim."}, "a": "D", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-07", "q": "You're Implementing a feature where users refine their playlist preferences through multiple conversation turns. After deploying, you notice Claude's responses don't reflect what us earlier in the same conversation— for example, a user says they love jazz, but two messages later Claude asks what genres they enjoy. What is the most likely cause?", "o": {"A": "The model's context window has been exceeded by the conversation length", "B": "The Claude API requires a session_id parameter that you haven't configured", "C": "Claude requires a vector database connection to maintain conversation memory", "D": "Your application isn't including prior messages in the messages array"}, "a": "D", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-08", "q": "During initial testing, you notice that Claude doesn't seem to remember vocabulary words from earlier in the conversation. When a student asks \"Can you quiz me on those words?\", responds as if no words have been discussed. What is the most likely explanation?", "o": {"A": "Your system prompt needs explicit instructions telling Claude to remember information from earlier turns.", "B": "You're not including prior messages in each API request—the stateless API doesn't retain conversation history.", "C": "You need to enable conversation persistence by passing a session ID parameter with each API call.", "D": "The model's context window has filled up, causing earlier conversation content to be dropped."}, "a": "B", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-09", "q": "Your home renovation planning assistant uses a system prompt defining an expert contractor persona with specific guidelines: always ask about budget, suggest alternatives at multiple price points, and confirm timeline requirements. During testing, responses follow these guidelines for turns 1-4, but by turn 7, the assistant gives generic advice without asking about budget or timeline. The conversation totals only 2,500 tokens. What is the most likely cause?", "o": {"A": "System prompts only establish initial behavior and don't persist across all turns.", "B": "The system prompt is only sent with the first API request.", "C": "The assistant's accumulated responses are diluting the system prompt's influence.", "D": "The model's attention on system prompt instructions naturally weakens as turns accumulate."}, "a": "C", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-10", "q": "Users report that during extended conversations, the AI loses track of specific topics, examples, and preferences they mentioned earlier in the session. Your current implementation uses a sliding window that keeps only the most recent 25 message pairs to stay within context limits. What's the most effective approach to maintain awareness of earlier conversation content while managing context size?", "o": {"A": "Replace the sliding window with a hybrid approach: summarize older messages while keeping recent messages verbatim.", "B": "Implement vector similarity search over the full conversation history, retrieving relevant past messages for each user query.", "C": "Increase the window size to 50 message pairs to retain more conversation history before truncation.", "D": "Add a separate API call each turn to summarize messages being dropped, prepending this running summary to the conversation."}, "a": "A", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-11", "q": "During QA testing, you notice that Claude follows your system prompt guidelines consistently in the first 10- 15 turns, but by turn 25-30, responses begin deviating—using informal tone when formality was specified, occasionally skipping required formatting, or providing information types the guidelines restrict. Conversation length is well within context limits (typically 30,000 tokens out of 200,000 available). What's the most effective approach to maintain consistent behavior throughout extended conversations?", "o": {"A": "Insert user-role messages that reinforce critical guidelines at natural conversation breakpoints, especially before complex requests.", "B": "Implement post-response validation that regenerates each response until it conforms to the specified guidelines.", "C": "Automatically start a new conversation after 20 turns, passing a summary of the prior context to maintain continuity.", "D": "Move behavioral guidelines from the system prompt into the first user message."}, "a": "A", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-12", "q": "Performance analysis reveals your context is composed of accumulated RAG results from all previous queries, which is crowding out conversation history and causing coherence degradation after 15+ turns. Which approach best addresses this issue?", "o": {"A": "Implement semantic deduplication to identify and remove redundant information across the accumulated RAG results and conversation turns", "B": "Implement a sliding window for RAG results from the last 2-3 queries while preserving conversation history", "C": "Shift context budget to favor RAG results while reducing conversation history allocation", "D": "Compress all RAG results into a consolidated summary document that updates incrementally after each retrieval"}, "a": "B", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-4.1-03", "q": "Your music discovery assistant should consistently maintain an enthusiastic tone, explain its reasoning for each recommendation, and ask clarifying questions to better understand user preferences. You want this behavior to persist reliably across all user interactions. Where should you define these behavioral guidelines?", "o": {"A": "In the first assistant message, instructing Claude to follow these guidelines going forward", "B": "Prepended to each user message before sending to the API", "C": "In the system prompt", "D": "In environmental variables that your application passes to the API client"}, "a": "C", "w": "", "c": "Prompting Techniques", "dup": "", "conflict": false, "ts": "ts-4.1"},
{"id": "ts-5.1-13", "q": "During a conversation about order tracking, your external system receives a webhook indicating the user's package has shipped. The user is actively chatting and will likely send a follow-up message soon. You want the assistant to naturally incorporate this status change in its next response. What's the most effective approach?", "o": {"A": "Immediately send an API request with the update as a synthetic user message, generating an unsolicited assistant response.", "B": "Append the status update as a prefix to the next user message before calling the API.", "C": "Configure the assistant to call a get_order_status tool at the start of every response.", "D": "Add the current shipping status to the system prompt before the next API call."}, "a": "D", "w": "", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.2-06", "q": "A new user's first message is \"Set up my focus music,\" This could mean configure preferences, create a playlist, or play music immediately. Your system supports all three actions. What's the effective approach?", "o": {"A": "Create a new \"Focus\" playlist with curated tracks and notify the user it's ready.", "B": "Ask one clarifying question about action type: play now or configure for later", "C": "Play popular focus tracks Immediately and let the user redirect if needed", "D": "Start preference configuration by asking about genres, temps, and artists they prefer for focus."}, "a": "B", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-4.1-04", "q": "Users report that responses feel repetitive across turns—each message begins with phrases like \"Certainly!\" or \"I'd be happy to help!\" even deep into conversations. You want responses to feel more natural, without these repetitive openers. What's the most effective approach?", "o": {"A": "Implement post-processing to detect and strip common greeting phrases from response beginnings", "B": "Add system prompt instructions specifying phrases to avoid, such as \"Never begin responses with 'Certainly' or similar affirmations\"", "C": "Lower the temperature parameter to make response openings more deterministic and less variable", "D": "Append a partial assistant message with a direct response opening that the model will continue from"}, "a": "D", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-4.1"},
{"id": "ts-2.1-11", "q": "Your update_user_profile tool accepts a user_id (required) and an optional fields_to_update object. In testing, Claude frequently omits user_id or passes incorrectly structured data. What is most critical for helping Claude understand what parameter values to provide?", "o": {"A": "Clear parameter descriptions explaining expected format, such as \"user_id : UUID of the user to update (required)\"", "B": "Verbose parameter names encoding format hints, such as user_id_string_uuid_format", "C": "Strict JSON Schema type constraints marking user_id as required and defining fields_to_update as an object type", "D": "Detailed error responses explaining why invalid parameter values were rejected"}, "a": "A", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.2-09", "q": "Production monitoring shows your search_catalog tool fails 12% of the time: 8% are network timeouts that succeed when immediately retried, while 4% are query syntax errors from malformed user-provided filters that never succeed regardless of retry attempts. Currently, both error types are returned to the agent identically, causing it to waste turns retrying syntax errors and telling users to \"try again later\" for timeouts. How should you modify the tool's error handling?", "o": {"A": "Apply exponential backoff retry logic to all errors uniformly, returning a generic \"service temporarily unavailable\" message after max retries are exhausted.", "B": "Return all errors with a retryable boolean flag and error type details.", "C": "Implement automatic retry with backoff for network timeouts inside the tool; return syntax errors immediately with parameter validation details.", "D": "Add few-shot examples to your system prompt demonstrating how to distinguish network errors from syntax errors and handle each case appropriately."}, "a": "C", "w": "", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-5.2-07", "q": "Users frequently send ambiguous requests like \"book a venue for the party\" without specifying date, guest count, or budget. Your evaluation shows the assistant asks an average of 4.2 clarifying questions before taking any action, causing 35% of users to abandon mid-conversation. However, when you reduce questions, users sometimes receive recommendations that don't match their preferences. What's the most effective approach to improve this trade-off?", "o": {"A": "Instruct the assistant to state explicit assumptions based on conversation history, proceed with recommendations while inviting corrections, and reserve clarifying questions only for irreversible actions like confirming bookings.", "B": "Configure the assistant to proceed with reasonable defaults (medium-sized venue, next weekend, moderate budget) without explicitly stating these assumptions, allowing users to provide corrections if results don't match expectations.", "C": "Implement a structured intake form that collects all required parameters (date, guest count, budget, venue type) upfront before the assistant begins providing any recommendations.", "D": "Configure the assistant to consolidate all clarifying questions into a single compound question (e.g., \"What date, guest count, and budget are you considering?\") to reduce the total number of conversational turns."}, "a": "D", "w": "", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-5.5-03", "q": "Your document extraction tool uses ML models to extract invoice fields (vendor, amount, date). The models return confidence scores (0.0-1.0) for each extracted field. In production, you observe: (1) the agent proceeds with low-confidence extractions that are incorrect 23% of the time, and (2) the agent requests unnecessary human review for 31% of extractions that were actually correct. How should you restructure the tool's output?", "o": {"A": "Return fields with their raw confidence scores and add detailed few-shot examples to your system prompt demonstrating how to interpret different confidence ranges and when to request human review.", "B": "Compute an aggregate extraction quality score across all fields and return it alongside the extracted values. Include a text summary describing the overall extraction reliability.", "C": "Return fields with confidence scores, plus a requires_review boolean computed using your tested confidence thresholds, along with a review_reasons array explaining which fields triggered review.", "D": "Return fields organized into verified and needs_verification objects based on confidence thresholds."}, "a": "C", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-5.5"},
{"id": "ts-2.1-12", "q": "Your agent includes an update_game_score tool that accepts game_date (string), home_team (string), and away_team (string) parameters. Production logs reveal recurring issues: the agent uses team nicknames instead of official names, applies inconsistent date formats, and selects the wrong game when teams have rematches in the same season. What tool interface change would effectively prevent these errors?", "o": {"A": "Add a season parameter to disambiguate rematches, and add a confirm_before_update flag that returns the resolved game details for the agent to verify before the score is committed.", "B": "Add detailed examples to the tool description showing the required date format and complete list of official team names.", "C": "Add enum constraints listing valid team names for both team parameters, and add a regex pattern enforcing ISO 8601 format for the date parameter.", "D": "Replace the three parameters with a single game_id parameter and a separate search_games lookup tool that returns matching game IDs."}, "a": "D", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-2.1-13", "q": "Your resource allocation tool returns a simple acknowledgment message after provisioning is requested. Users frequently approve allocations and immediately ask \"how much did that cost?\" or \"which project was that?\" - indicating they confirmed without understanding the request. What tool design change would most effectively address this?", "o": {"A": "Add a user_acknowledged: boolean parameter that must be set true, with instructions for the agent to only set it after the user explicitly confirms they reviewed the details", "B": "Implement a 60-second hold before execution completes, allowing users time to review pending allocations and cancel if needed", "C": "Add a detail_level parameter with options \"minimal\" or \"comprehensive\" that controls how much context the agent presents in confirmations", "D": "Return structured data including cost estimate, target project, resource specifications, and impact summary in the tool response"}, "a": "D", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.1"},
{"id": "ts-5.1-14", "q": "Your conversation history includes two types of content: persistent story elements (character backgrounds, plot structure, world rules) that must remain consistent throughout, and extensive brainstorming discussion that's mostly ephemeral. After 40+ turns, you're hitting context limits and users report the assistant \"forgets\" established character traits, breaking narrative consistency. Which approach best ensures persistent story elements remain available to the model while reclaiming context space?", "o": {"A": "Separate persistent story elements into a retained \"story bible\" section at context start, applying trimming or summarization only to brainstorming discussion.", "B": "Store all history in a vector database and retrieve semantically similar passages for each new message, replacing conversation history with retrieved chunks.", "C": "Apply a sliding-window approach keeping only the most recent 25 turns, relying on the model to infer earlier context from recent discussion flow.", "D": "Summarize the entire conversation history into a condensed synopsis every 20 turns, replacing the full history to free up tokens."}, "a": "A", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.2-08", "q": "Your conversational assistant frequently generates multiple clarifying questions when users make ambiguous requests. When a user asks \"Can you help me with the report?\", the assistant responds: \"I'd be happy to help! Could you tell me: 1) Which report? 2) What kind of help—drafting, reviewing, or formatting? 3) What's your deadline?\" User analytics show a 40% conversation abandonment rate after these multi-question responses. What's the most effective way to reduce friction while appropriately handling ambiguity?", "o": {"A": "Limit the assistant to one clarifying question per turn, using conversation history to accumulate answers over multiple exchanges rather than requesting everything upfront.", "B": "Modify the system prompt to instruct the assistant to make reasonable assumptions from available context, state those assumptions explicitly, and offer to adjust if the interpretation is wrong.", "C": "Add a preprocessing step using a smaller model to classify request ambiguity on a 1-5 scale, routing high-ambiguity requests to a clarification dialog and low-ambiguity requests directly to the assistant.", "D": "Create a lookup table of common request patterns with predefined default interpretations, having the assistant respond with those defaults without stating the assumptions made."}, "a": "B", "w": "", "c": "Cost & Latency", "dup": "", "conflict": false, "ts": "ts-5.2"},
{"id": "ts-5.1-15", "q": "Users frequently refine their search criteria mid-conversation. You notice a pattern: when users say things like \"Actually, let's raise the budget to $650K\" or \"I'd prefer a condo now instead of a house,\" the assistant sometimes continues referencing the original preferences in later responses—even though the updates are clearly present in the conversation history. Context usage is only at 35% capacity. Which solution most reliably ensures the model uses the current preferences?", "o": {"A": "Maintain a structured state object with current preferences, update it on changes, and include it in each request.", "B": "Implement conversation pruning to remove turns containing outdated preferences, ensuring only current ones remain in context.", "C": "Include few-shot examples showing the assistant correctly acknowledging and applying preference changes in responses.", "D": "Add system prompt instructions emphasizing that the model should always prioritize the most recently stated preferences over earlier ones."}, "a": "A", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-16", "q": "Your conversational AI tutor has a 2,800-token system prompt containing teaching methodology, persona guidelines, and detailed written instructions for adapting explanations to different proficiency levels. User testing reveals that in conversations exceeding 12 turns (approximately 4,000 tokens of conversation history), the assistant increasingly ignores the proficiency-adaptation guidelines, defaulting to intermediate-level explanations regardless of the learner's stated level. What's the most effective approach to ensure consistent adherence to these guidelines throughout extended conversations?", "o": {"A": "Inject a condensed reminder of the proficiency requirements into the conversation as a system message every 4-5 turns.", "B": "Replace the verbose proficiency guidelines with few-shot examples demonstrating appropriate responses at each proficiency level, showing concrete differences in vocabulary, complexity, and explanation depth.", "C": "Restructure the system prompt to place the proficiency-adaptation rules in a clearly-marked final section immediately before the conversation history begins.", "D": "After each assistant response, make a separate API call to evaluate whether the difficulty level matched the learner's profile, regenerating responses that don't align."}, "a": "B", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-17", "q": "After deploying an updated system prompt that improves response quality, users with multi-session conversations spanning several weeks report that the assistant now contradicts its earlier statements and has a noticeably different communication style. New users don't experience these issues. What's the best approach to resolve this?", "o": {"A": "Regenerate summaries of existing conversations using the new prompt and replace the stored histories to align past context with current behavior.", "B": "Add a transition message when sessions resume explaining that the assistant has been updated and behavior may differ.", "C": "Version system prompts and associate each conversation with the prompt version under which it started, applying updates only to new conversations.", "D": "Add instructions to the new system prompt directing the assistant to maintain consistency with any prior statements in the conversation history."}, "a": "C", "w": "", "c": "Prompting Techniques", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-5.1-18", "q": "Evaluation shows 94% extraction accuracy on short meeting transcripts (<30 minutes) but only 68% on longer transcripts (>60 minutes) where discussions meander and key information is scattered throughout. Transcripts of both lengths fit within the model's context window. What pattern most effectively improves accuracy on complex, lengthy documents?", "o": {"A": "Add few-shot examples demonstrating correct extraction from lengthy meetings with scattered Information.", "B": "Split lengthy transcripts Into chunks, extract from each chunk separately, then merge and deduplicate the results.", "C": "Upgrade to a more capable model tier for the extraction task,", "D": "Add a pre-extraction step where the model summarizes key discussions and conclusions before performing structured extraction."}, "a": "B", "w": "", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-4.2-04", "q": "Your system has been running for 3 weeks and human reviewers have corrected 847 extractions. Analysis reveals a recurring pattern: when recipes use informal measurements like \"a handful\" or \"a splash,\" the model either invents specific amounts or leaves fields empty—accounting for 23% of all corrections. How should you use this feedback to improve extraction accuracy?", "o": {"A": "Update your JSON schema to add a \"measurement_type\" enum field (precise/informal).", "B": "Add few-shot examples to your prompt demonstrating correct handling of informal measurements— extracting them verbatim rather than converting or omitting them.", "C": "Implement a post-processing layer that uses pattern matching to detect informal measurement phrases in source text and automatically populate values when the extraction is empty.", "D": "Fine-tune the model on the 847 corrected extractions."}, "a": "B", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.2"},
{"id": "ts-5.5-04", "q": "The system routes documents with extraction confidence below 85% to human review. A quarterly audit reveals that 12% of high-confidence extractions (>85%) also contain errors—cases where the model finds plausible-but-incorrect values. Error sources vary: comparison tables showing competitor specs, appendices referencing different product variants, and ambiguous phrasing the model misinterprets. You need a sustainable strategy to catch these high-confidence errors and measure whether improvements reduce the error rate over time. What approach is most effective?", "o": {"A": "Implement heuristic rules that flag documents containing comparison tables or appendices for review regardless of confidence score.", "B": "Implement stratified random sampling reviewing a fixed percentage of high-confidence extractions weekly, enabling error rate measurement and novel pattern detection.", "C": "Add a verification pass that re-extracts from each high-confidence document, flagging cases where the two extraction attempts produce different results.", "D": "Lower the confidence threshold from 85% to 70%, routing a larger volume of extractions to human review."}, "a": "B", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-5.5"},
{"id": "ts-5.1-19", "q": "Your research assistant helps users analyze academic papers over extended conversations. User testing reveals a recurring issue: after conversations exceed 60K tokens, users ask follow-up questions requiring precise numerical details from papers discussed earlier—sample sizes, exact p-values, specific inclusion criteria. Your current approach summarizes paper discussions after 8 turns to stay within context limits. Users report that responses to these precision-dependent questions are often hedged or inaccurate. What's the most effective architectural change?", "o": {"A": "Implement retrieval that re-injects relevant paper sections when the user's question suggests they need specific numerical details.", "B": "Maintain a structured database of key facts extracted from each paper (sample sizes, statistics, methods) and retrieve relevant entries into context when precision-dependent questions are detected.", "C": "Keep source text from methodology and results sections in context permanently, while summarizing only the conversational discussion and interpretation portions.", "D": "Use a separate Claude call with explicit instructions to generate higher-fidelity summaries that preserve all numerical details and statistical values."}, "a": "B", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-5.1"},
{"id": "ts-4.1-05", "q": "Your fitness coaching assistant uses a system prompt with detailed conditional logic: \"If the user mentions being a beginner, provide step-by-step form instructions. If they use terms like 'progressive overload' or 'superset', respond concisely. If they ask about injury history, always recommend consulting a physician.\" During evaluation, you find the assistant correctly adapts to explicit expertise declarations but struggles when users don't clearly state their level—often defaulting to overly detailed responses regardless of contextual cues like technical terminology. Which change to the system prompt would most directly address this failure to pick up on implicit expertise signals?", "o": {"A": "Add an explicit instruction for the model to ask a clarifying question about experience level whenever the user's expertise isn't immediately clear from their first message.", "B": "Replace most conditionals with a general principle: \"Adapt explanation depth to match user expertise, mirroring their terminology.\" Keep only the safety-critical conditional about injury consultations.", "C": "Implement a pre-conversation intake that asks users to rate their experience level, then inject that rating into the system prompt as context for all subsequent responses.", "D": "Add more conditional branches to cover additional expertise signals, such as \"If user mentions specific rep ranges or asks about periodization, treat as advanced.\""}, "a": "B", "w": "", "c": "Prompting Techniques", "dup": "", "conflict": false, "ts": "ts-4.1"},
{"id": "ts-4.6-01", "q": "\"You're the Lead Data Scientist/Engineer on a critical project. Something is not completely right with technical details or the data, and it negative impacts expected outputs. They need to independently develop both approaches to evaluation data... How do you manage this scenario?\"", "o": {"A": "Start two fresh sessions, having each re-read the relevant source files before beginning.", "B": "Continue in the original session, developing end-to-end tests first, then snapshot tests sequentially.", "C": "Resume the analysis session with fork_session enabled, creating a separate branch for each testing strategy.", "D": "Export the analysis session's key findings to a file, then create two new sessions that reference this file."}, "a": "C", "w": "", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-4.6"},
{"id": "ts-5.4-10", "q": "A security audit requires updating your authentication library from v2 to v3. The migration guide documents breaking changes: authenticate() now returns a Promise instead of accepting a callback, the User type has restructured fields, and three deprecated methods were removed. Grep shows the library is imported in 45 files across several modules. What's the most effective approach?", "o": {"A": "Paste the migration guide's breaking changes into your prompt and use direct execution to update all usages across the 45 files.", "B": "Enter plan mode to explore library usage across modules, map affected code paths, then create a migration strategy before implementing.", "C": "Update the dependency version, run the test suite, and use Claude Code to fix each failure as it appears.", "D": "Create a custom slash command encapsulating the migration transformations, then execute it against each file without prior codebase exploration."}, "a": "B", "w": "", "c": "Codebase Search (Glob/Grep)", "dup": "", "conflict": false, "ts": "ts-5.4"},
{"id": "ts-3.4-01", "q": "You need to add a date validation check ensuring event dates are in the future. This requires adding a conditional statement to one existing function in a single file. What is the most appropriate approach?", "o": {"A": "Enter plan mode to analyze how the validation might impact other parts of the reservation flow", "B": "Start with extended thinking mode enabled to ensure thorough reasoning about the validation logic", "C": "Use direct execution to make the change", "D": "Enter plan mode first to create a detailed implementation strategy before making the change"}, "a": "C", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-3.4"},
{"id": "ts-1.5-04", "q": "Your team's CLAUDE.md includes a rule: \"Use 4-space indentation and always run Prettier formatting.\" Despite this, code reviews reveal that roughly 30% of files Claude Code generates use inconsistent formatting — sometimes 2-space indentation, sometimes missing trailing commas. Adding emphasis (\"IMPORTANT: You MUST use Prettier formatting\") reduces violations to about 15%, but doesn't eliminate them. What is the most effective way to ensure all generated code is consistently formatted?", "o": {"A": "Extract the formatting rules into a dedicated skill that Claude loads automatically when generating code, with more detailed examples of correct formatting.", "B": "Add a Stop hook with a prompt-based check that evaluates whether generated code follows formatting standards and prompts Claude to fix violations.", "C": "Configure a Post ToolUse hook with an Edit|Write matcher that automatically runs Prettier on each file Claude modifies.", "D": "Split the formatting rules into path-scoped .claude/rules/ files that load when Claude works on matching file types."}, "a": "C", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-1.5"},
{"id": "ts-3.5-02", "q": "You've asked Claude Code to build a PDF report generation feature. The initial implementation queries the database correctly, but the output has formatting issues: table columns are too narrow causing content truncation, dates display without proper formatting, and page break handling is incorrect. You've noticed these issues interact— changing column widths affects how dates render, and page breaks depend on content height. What's the most effective approach for iterating toward a working solution?", "o": {"A": "Address the column width issue first with specific measurements, verify it works, then fix date formatting within the corrected columns, then adjust page breaks— testing after each change.", "B": "Provide all three issues in a single detailed message with exact specifications for each, allowing Claude to address them together in one update.", "C": "Show Claude an example of a correctly formatted report and ask it to match that output, rather than listing the specific technical issues.", "D": "Start fresh with a detailed prompt specifying all formatting requirements upfront."}, "a": "A", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-3.5"},
{"id": "ts-3.4-02", "q": "You're implementing a caching layer for API responses to speed up the /products endpoint. You have a rough idea—Redis with a 5-minute TTL—but you're new to production caching and aren't sure what other considerations a robust implementation requires. What's the most effective way to start your iterative workflow?", "o": {"A": "Ask Claude to interview you about the caching requirements before implementing, surfacing considerations like invalidation strategies, cache layers, consistency guarantees, and failure modes.", "B": "Use plan mode to analyze the current/products endpoint implementation, then provide your caching requirements once Claude explains how the existing code is structured.", "C": "Start with a minimal request: \"Add Redis caching to/products with 5-minute TTL.\" Add features and fix issues through follow-up prompts as problems surface during testing.", "D": "Write a specification with your known requirements and \"TBD\" markers for uncertain areas, having Claude propose solutions for each TBD as it implements."}, "a": "A", "w": "", "c": "Cost & Latency", "dup": "", "conflict": false, "ts": "ts-3.4"},
{"id": "ts-3.5-03", "q": "You're implementing a complex graph traversal algorithm with specific performance requirements and edge cases to handle (disconnected nodes, cycles, weighted edges). You want to structure your workflow for efficient iterative refinement with Claude. What approach will most effectively enable progressive improvement across multiple iterations?", "o": {"A": "Write a test suite covering expected behavior, edge cases, and performance requirements before implementation. Ask Claude to write code that passes the tests, then iterate by sharing test failures with each refinement request.", "B": "Provide Claude with a detailed natural language specification of the algorithm, including all requirements and edge cases. Review each output manually and provide descriptive feedback on what behavior needs to change.", "C": "Provide Claude with a reference implementation from documentation, then ask it to rewrite the code to match your codebase style and add the required edge case handling, comparing outputs against the reference.", "D": "Have Claude extensively research the algorithm and create a detailed implementation plan using extended thinking, then implement the complete solution based on that plan."}, "a": "A", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-3.5"},
{"id": "ts-2.4-03", "q": "Your team is configuring MCP servers in Claude Code. You want to add a shared venue lookup server that all team members should have access to, and you personally want to add an experimental music playlist server that only you are testing. Which configuration approach correctly applies MCP server scopes?", "o": {"A": "Add venue server to .mcp.json and playlist server to ~/.claude.json", "B": "Add both servers to the project-level .mcp.json file", "C": "Add venue server to ~/.claude.json and playlist server to .mcp.json", "D": "Add both servers to your local ~/.claude.json"}, "a": "A", "w": "", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.4"},
{"id": "ts-3.3-01", "q": "Your infrastructure-as-code repository includes Terraform modules (/terraform/), Kubernetes manifests (/kubernetes/), and CI/CD pipeline scripts (/pipelines/). Each requires different conventions, but your single root CLAUDE.md has grown to 500+ lines. When developers work on Kubernetes files, Terraform-specific rules load into context unnecessarily, consuming tokens. What is the best approach to reorganize so only relevant guidance loads when editing specific file types?", "o": {"A": "Restructure the root CLAUDE.md into clearly labeled sections with headers (e.g., \"## Terraform Conventions\"), improving organization and readability.", "B": "Split content into subdirectory CLAUDE.md files (/terraform/CLAUDE.md, /kubernetes/CLAUDE.md), so Claude loads directory-specific guidance.", "C": "Keep the root CLAUDE.md and use @path/to/import syntax to modularly include tool-specific guidance files from separate documents.", "D": "Create files in .claude/rules/ with YAML frontmatter path-scoping (e.g., paths: [\"terraform/**/*\"]), loading rules only when editing matching files."}, "a": "D", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-3.3"},
{"id": "ts-3.2-01", "q": "Your team frequently migrates React components to Vue. You've written a step-by-step workflow for Claude Code to follow during each migration, and you want every developer on the team to invoke it by typing /migrate-component. The workflow should stay in sync as the team iterates on it. Where should you place the skill file?", "o": {"A": "In ~/.claude/skills/migrate-component/SKILL.md on each developer's machine", "B": "In the project's .claude/settings.json using a skillOverrides entry to register and define the workflow", "C": "In .claude/skills/migrate-component/SKILL.md at the project root, committed to version control", "D": "As a detailed instruction block in the project's root CLAUDE.md file"}, "a": "C", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-3.2"},
{"id": "ts-3.5-04", "q": "You're implementing a new payment processing module that must follow your project's established patterns for database transactions, error handling, and audit logging. You've identified three existing modules that exemplify these patterns: db_utils.py, error_handlers.py, and audit_logger.py. This is a one-off integration task—these patterns are well-documented in your team wiki and don't need additional project-level documentation. What's the most effective approach?", "o": {"A": "Describe the patterns from the three modules in natural language in your prompt, explaining the transaction handling approach, error format, and logging conventions Claude should follow.", "B": "Use @references to include the three modules directly in your prompt, giving Claude concrete code examples of the patterns to follow.", "C": "Ask Claude to explore your codebase to find and understand the transaction, error handling, and logging patterns before generating the new module.", "D": "Add documentation of each pattern to your CLAUDE.md file, establishing them as project conventions that Claude will apply automatically."}, "a": "B", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-3.5"},
{"id": "ts-3.5-05", "q": "You've asked Claude to write a data migration script, but the initial output doesn't correctly handle records with null values in required fields. What's the most effective way to iterate toward a working solution?", "o": {"A": "Provide a test case with example input containing null values and the expected output, then ask Claude to fix it.", "B": "Manually edit the generated code to fix the null handling, then continue working with Claude on other parts.", "C": "Describe the null value problem in detail and ask Claude to regenerate the entire script with improved edge case handling.", "D": "Add \"think harder about edge cases\" to your prompt and request a complete rewrite of the migration logic."}, "a": "A", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-3.5"},
{"id": "ts-3.1-01", "q": "You've documented API error handling conventions in a CLAUDE.md file at your project root, specifying that endpoint handlers should use a custom ApiError class. After several sessions, you notice Claude Code sometimes follows these conventions and sometimes uses generic try/catch blocks with string messages. The inconsistency appears random across different coding sessions. What's the most efficient first diagnostic step?", "o": {"A": "Add more detailed code examples to your CLAUDE.md showing the exact ApiError usage pattern for different endpoint types.", "B": "Run /memory to check which memory files are loaded and verify your CLAUDE.md is included.", "C": "Search for conflicting instructions in ~/.claude/CLAUDE.md or ~/.claude/rules/ that might override your project conventions.", "D": "Create path-specific rules in claude/rules/handlers.md with YAML frontmatter scoping the error handling instructions to your API handler files."}, "a": "B", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-3.1"},
{"id": "ts-3.1-02", "q": "Your monorepo contains shared coding standards in /docs/standards/security-rules.md (for services handling user data), testing-patterns.md (for all packages), and api-conventions.md (for API-facing services). Your 15 packages are organized by feature domain (/packages/auth/, /packages/billing/, /packages/notifications/, etc.) without naming conventions indicating which handle user data or expose APIs. Package maintainers are expected to configure their own local development settings, as they understand their package's domain requirements. Currently, all package CLAUDE.md files duplicate all three standards, applying irrelevant guidance. What's the most effective approach?", "o": {"A": "Create claude/rules/ files for each standard with YAML frontmatter paths listing every package directory where that standard should apply.", "B": "Create a shared-standards.nd that uses @imports to combine all three standards, then have each package's CLAUDE.md import that combined file.", "C": "Put all standards in the root CLAUDE.md with override instructions like \"ignore security-rules.md when working in packages that don't handle user data.\"", "D": "Use @imports in each package's CLAUDE.md to reference only the specific standard files relevant to that package, based on the maintainer's domain knowledge."}, "a": "D", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-3.1"},
{"id": "ts-4.2-05", "q": "The system processes product reviews using tool use with a defined schema: rating (integer 1-5), pros (string array), cons (string array), and overall_sentiment (enum: positive, negative, mixed). Testing reveals two issues with brief or ambiguous reviews (~20% of the dataset): (1) for reviews like \"Great product!\", Claude fabricates specific pros and cons rather than indicating this information isn't explicitly stated, and (2) for sarcastic reviews like \"Well that was... interesting\", Claude picks sentiment arbitrarily since there's no option for ambiguous cases. What schema modification best addresses both issues?", "o": {"A": "Add an extraction_confidence field (0.0-1.0) for each value, and filter outputs where any confidence falls below a threshold.", "B": "Allow null values for pros/cons, and add \"unclear\" to the sentiment enum.", "C": "Allow empty arrays for pros/cons as valid output, and add \"unclear\" to the sentiment enum.", "D": "Make pros and cons optional fields, and add \"neutral\" and \"unclear\" to the sentiment enum."}, "a": "C", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.2"},
{"id": "ts-4.3-06", "q": "The system needs to extract candidate information (name, contact details, skills, work experience, education) from uploaded resumes. The extracted data must strictly conform to a predefined JSON schema, as missing required fields or incorrect data types will cause downstream validation failures. What is the most reliable approach to ensure Claude's output consistently matches the schema?", "o": {"A": "Define a tool with an input schema matching your required JSON structure and extract the data from Claude's tool_use response.", "B": "Include detailed JSON formatting instructions and a template example in the system prompt, asking Claude to output only valid JSON.", "C": "Parse Claude's text response with regex patterns to extract JSON objects, using retry logic for malformed responses.", "D": "Make two separate API calls—first extracting information as text, then asking Claude to format that text as JSON."}, "a": "A", "w": "", "c": "Structured Output & Extraction", "dup": "", "conflict": false, "ts": "ts-4.3"},
{"id": "ts-4.4-06", "q": "After deploying automated code review, developers report that approximately 35% of flagged findings are false positives falling into consistent patterns: style suggestion contradicting team conventions, security warnings for patterns safe in your deployment context, and performance suggestions that would degrade your specific use ca. You want to reduce false positives while maintaining the ability to catch genuine issues. Which approach best enables the model to generalize its judgment to novel co patterns it hasn't seen before?", "o": {"A": "Include few-shot examples in your prompt showing annotated code snippets that distinguish acceptable patterns from genuine issues in each category.", "B": "Implement post-processing that uses keyword matching to filter out findings containing terms like \"convention,\" \"context-dependent,\" or \"trade-off.\"", "C": "Add instructions to your system prompt to \"be conservative,\" \"only flag definite issues,\" and \"consider that some patterns may be intentional.\"", "D": "Create a comprehensive written specification of all patterns that should not be flagged, then include this full documentation in the system prompt."}, "a": "A", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-4.4"},
{"id": "ts-2.3-03", "q": "After expanding the agent's MCP tools with delivery-specific capabilities (check_delivery_status, contact_driver, issue_credit, apply_promo_code, update_delivery_address, reschedule_delivery), the total tool count has grown from 4 to 10. Your evaluation suite shows tool selection accuracy has dropped to 71%. Log analysis reveals the majority of errors involve the agent selecting between semantically overlapping tools- calling issue_credit when process_refund is correct, and calling check_delivery_status when lookup_order already returns the needed data. Which approach structurally eliminates the semantic overlaps that are being logged as the error source?", "o": {"A": "Split the tools across two sub-agents - a \"financial resolution\" agent with process_refund, issue_credit, and apply_promo_code, and a \"delivery\" agent with the remaining delivery tools - with a coordinator routing between them.", "B": "Add few-shot examples to the system prompt demonstrating correct selection for each ambiguous tool pair, such as showing when issue_credit or process_refund is appropriate.", "C": "Consolidate semantically overlapping tools-merge issue_credit and process_refund into a single resolve_compensation tool with an optional include_tracking flag.", "D": "Enable the tool search tool with defer_loading on the six new tools, keeping the original four always loaded, so the agent dynamically calls it when needed."}, "a": "C", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.3"},
{"id": "ts-2.2-10", "q": "Anthropic's tool use documentation states: \"Write instructive error messages. Instead of generic errors like 'failed', include what went wrong and what Claude should try next.\" A billing dispute agent uses lookup_order, which catches all exceptions and returns a tool_result with is_error: true and the message \"execution failed\". Monitoring shows two failure modes: the agent retries the identical call until hitting the turn limit, or it immediately calls escalate_to_human without trying alternative tools. Which change follows the documented recommendation and gives Claude the information it needs to select the correct recovery action for each error type?", "o": {"A": "Implement retry logic with exponential backoff inside each tool implementation so transient errors are resolved transparently within the tool before any failure result is surfaced to Claude in the agentic loop.", "B": "Return error-type-specific messages with is_error: true, e.g., \"order not found-try get_customer to search by phone\" for data errors and \"Database timeout (transient)-retry should succeed\" for infrastructure errors.", "C": "Remove is_error: true and return the error details as normal tool content, so Claude reasons about the response as data rather than treating it as a flagged failure condition that biases retry behavior.", "D": "Add an error classification step in the agentic loop that intercepts tool errors before Claude sees them, tags each as \"retry\" \"try_alternative,\" or \"escalate,\" and adds that recommendation to the tool result."}, "a": "B", "w": "", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-4.1-06", "q": "Your code review prompts include both implementation changes and the corresponding test file, but the LLM's review comments fail to point out untested code paths. Analysis reveals the model correctly flags functions that have no tests at all, but fails to identify when conditional branches or error-handling paths within tested functions that have no tests at all, but fails to identify when conditional branches or error-handling paths within tested functio lack coverage. What's the most effective way to improve detection of branch-level coverage gaps without overcomplicating the pipeline?", "o": {"A": "Implement a multi-pass pipeline where separate LLM calls first extract all conditional branches, then cross-reference each against test assertions in a second pass.", "B": "Include few-shot examples showing code with an uncovered branch paired with the review comment identifying the specific missing test case.", "C": "Add explicit instructions directing the model to enumerate each conditional branch and exception path, then verify each has a corresponding test assertion.", "D": "Restructure the prompt to interleave implementation and tests, presenting each function followed immediately by its test cases"}, "a": "B", "w": "", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-4.1"},
{"id": "ts-4.6-02", "q": "Your automated reviewer uses a single prompt covering security issues, API design, and business logic correctness. Your evaluation suite shows strong recall findings (82%) but poor recall for business logic edge cases in quiz scoring (34%). When you add few-shot examples of logic bugs to the prompt, logic recall is 41% but API design recall drops to 68%. How should you address this trade-off to improve detection across both categories?", "o": {"A": "Split the review into separate focused prompts - one for security and API design, another for business logic - each with dedicated examples, then combine findings before posting.", "B": "Upgrade to a more capable model tier, since its stronger reasoning will handle both concern types in a single prompt and eliminate the recall trade-off.", "C": "Provide the full repository as context instead of just the changed files and surrounding code, giving the model deeper visibility into business logic.", "D": "Replace the few-shot examples with a detailed checklist of specific logic edge cases to verify, such as division-by-zero in score calculation or grading thresholds."}, "a": "A", "w": "", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-4.6"},
{"id": "ts-1.1-04", "q": "Production logs show that when the agent handles complex billing disputes requiring 6+ tool calls, it sometimes exhausts its max_turns limit after gathering data and before completing resolution or escalating. The team's goal is to guarantee that every customer interaction ends with either a completed resolution or a human escalation, regardless of how the agent loop terminates. Which approach achieves this guarantee?", "o": {"A": "Add orchestration-layer code that checks the agent's outcome after each loop termination - if the loop ended without a completed resolution or escalation, programmatically call escalate_to_human with the accumulated conversation context and tool results.", "B": "Implement a pre-tool-use hook that counts tool invocations and terminates the loop with an automatic escalation once the agent reaches 80% of its remaining actions.", "C": "Add system prompt instructions telling the agent to call escalate_to_human with a summary of its findings whenever it determines it cannot resolve the dispute.", "D": "Split the workflow into two sequential agent invocations — a first agent gathers information via get_customer and lookup_order, then the second agent uses that data and handles process_refund or escalate_to_human, each with separate turn budgets."}, "a": "A", "w": "", "c": "Reliability & Guardrails (Hooks)", "dup": "", "conflict": false, "ts": "ts-1.1"},
{"id": "ts-1.6-03", "q": "In production, you observe that simple fact-checking queries (e.g., \"What year was the Paris Climate Agreement signed?\") traverse all four subagents sequentially, consuming 40+ seconds and significant tokens per query. Complex comparative research benefits from the full pipeline. Your query distribution is diverse and evolving as users discover new applications. What's the most effective approach to optimize for varying query complexity?", "o": {"A": "Have the coordinator analyze each query and dynamically decide which subagents to invoke based on its assessment of query requirements.", "B": "Train a query complexity classifier on labeled historical data to predict optimal subagent combinations, retraining periodically as query patterns evolve.", "C": "Create a fast-path for factual questions that bypasses subagents entirely, routing all other queries through the complete pipeline to ensure research thorough", "D": "Implement pattern-based routing that categorizes queries by structure (single-fact vs. comparative vs. analytical) and maps each category to a predefined combination."}, "a": "A", "w": "", "c": "Multi-Agent & Subagents", "dup": "", "conflict": false, "ts": "ts-1.6"},
{"id": "ts-4.6-03", "q": "Your automated review calls the Claude API for each PR, using tool_use with a report_findings tool that returns a JSON array of finding objects (each with file_path, line_number, severity, category, and description). During testing on a large PR touching 30+ files, the response hits the max_tokens limit and the output is truncated mid-JSON, causing your pipeline's parser to fail. What is the most effective way to handle this?", "o": {"A": "Increase max_tokens to the model's maximum and instruct Claude to keep finding descriptions under 50 words each.", "B": "Switch from tool_use to prompting Claude to return findings as a markdown list.", "C": "Split the review into multiple API calls that each analyze a subset of the changed files, then merge the resulting findings arrays.", "D": "Add retry logic that detects truncated JSON and re-sends the request with instructions to report only critical and high severity findings."}, "a": "C", "w": "", "c": "Context & Memory Management", "dup": "", "conflict": false, "ts": "ts-4.6"},
{"id": "ts-3.6-01", "q": "You are setting up a non-interactive automated code review pipeline using Claude Code. You want Claude to analyze a pulled Git diff (git diff) against the main branch and apply a custom set of code review instructions. However, you notice that when you run the pipeline, Claude only looks at the raw diff text itself and completely stops using its file-reading or code navigation tools. As a result, it fails to inspect the broader codebase repository context, which is critical because the diff modifies a core function called by many other external modules. Which change to the CLI invocation will cause Claude to read related files in the repository while still successfully applying your custom review instructions?", "o": {"A": "Replace --system-prompt with --append-system-prompt so your review instructions are added to Claude Code's default prompt instead of overwriting the built-in guidance for using file-reading and code navigation tools.", "B": "Keep --system-prompt and add --allowedTools \"Read, Glob, Grep\" so that the non-interactive mode permits file system tools that it otherwise disables.", "C": "Stop piping the diff via stdin and instead embed the diff contents inside the prompt string, so Claude Code treats the invocation as an agentic session rather than a stream-processing one.", "D": "Remove --system-prompt entirely and place the review instructions in a CLAUDE.md file at the repo root, since --system-prompt is incompatible with tool use under -p."}, "a": "A", "w": "", "c": "Error Handling", "dup": "", "conflict": false, "ts": "ts-3.6"},
{"id": "ts-3.5-06", "q": "Your development team is using Claude Code to automate test generation across a large codebase. However, developers are frequently rejecting the generated test suites because Claude creates a high volume of trivial assertions or tests that merely maximize line coverage without validating meaningful behavioral logic or edge cases. You want to guide Claude to generate high-quality, production-ready tests directly without introducing high latency or modifying the core pipeline script. Which strategy best ensures that high-quality, meaningful tests are generated in the first place?", "o": {"A": "Restrict test generation to directories where historical quality metrics show higher acceptance rates, disabling it for areas where generated tests consistently require heavy editing.", "B": "Add post-generation coverage analysis that automatically filters out any generated test that doesn't increase line coverage beyond what existing tests provide.", "C": "Document testing standards in CLAUDE.md including valuable test criteria, available fixtures with intended use cases, and examples distinguishing meaningful behavioral tests from trivial assertions.", "D": "Implement a two-phase generation where a second Claude call scores each test against quality criteria, filtering out low-scoring tests before presenting results to developers."}, "a": "C", "w": "", "c": "Evaluation & Testing", "dup": "", "conflict": false, "ts": "ts-3.5"},
{"id": "ts-4.6-04", "q": "A developer uses Claude Code to refactor a function during their development session. Before committing, they ask the same Claude session to review the code for issues. Later, a separate automated CI review catches several bugs that the same-session review missed. What best explains this discrepancy?", "o": {"A": "The CI environment has access to the full codebase context while the local session only sees the current file", "B": "The CI review uses a more specific prompt tailored for catching bugs, while the developer's request was too general", "C": "Claude retains context about its prior reasoning in the session, making it less likely to question its own decisions", "D": "The extended session length caused the context window to fill with conversation history, leaving less room for thorough analysis"}, "a": "C", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-4.6"},
{"id": "ts-2.5-05", "q": "An engineer sees an unfamiliar error message \"SYNC_CONFLICT: entity version mismatch detected\" in production logs but doesn't know which of the 12 services in the codebase generates it. They ask the agent to help locate the source code. What exploration approach will most efficiently find the responsible code?", "o": {"A": "Use Grep to search for distinctive text from the error message (like \"SYNC_CONFLICT\" or \"entity version mismatch\"), then Read the matching files to understand context.", "B": "Use Glob to find files in directories commonly associated with error handling (such as errors/, exceptions/, or handlers/) across services, then Read each matching file.", "C": "Use Grep to find all files that import the project's error handling module, then Read those files to locate custom error definitions.", "D": "Read the project's README and service configuration files to understand the architecture, then systematically Read source files in service directory."}, "a": "A", "w": "", "c": "Mixed / Applied Scenarios", "dup": "", "conflict": false, "ts": "ts-2.5"},
{"id": "ts-2.4-04", "q": "You've configured your Claude agent with three MCP servers: one for git operations, one for Jira ticket management, and one for documentation search. When a user asks the agent to \"create a branch for JIRA- 123 and add documentation links to the ticket,\" how does the agent access tools across these servers?", "o": {"A": "The agent queries each server sequentially to determine which handles each tool, routing calls based on tool name prefixes.", "B": "Tools from all configured MCP servers are discovered at connection time and available simultaneously to the agent.", "C": "You must specify which MCP server to use for each turn, and the agent can only access one server's tools at a time.", "D": "The agent automatically selects the most relevant server based on the request and loads only that server's tools."}, "a": "B", "w": "", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.4"},
{"id": "ts-2.2-11", "q": "Production logs reveal inconsistent error handling: when tool_code fails, the agent sometimes retries 5 times (even if the tool_id doesn't exist), sometimes escalates immediately (premature for temporary network issues), and sometimes adds user-friendly explanation (inappropriate when the issue is a backend permission error). Investigation shows four MCP tool returns uniform error responses: {\"status\": \"error\", \"content\": \"{\"type\": \"Error\", \"message\": \"Operation failed.\"}\"}. The agent learns different types. What's the most effective improvement?", "o": {"A": "Implement retry logic with exponential backoff in your MCP server for all errors, returning to the agent only after retries are exhausted.", "B": "Create an analyze_error MCP tool the agent calls after any failure to determine the error category and recommended action.", "C": "Add a few-shot examples to the system prompt demonstrating how to interpret error message patterns and select appropriate responses for each.", "D": "Enhance error responses with structured metadata. Include error_category (transient/retriable/permission), reason, and a description of what caused the failure."}, "a": "D", "w": "", "c": "MCP & Integrations", "dup": "", "conflict": false, "ts": "ts-2.2"},
{"id": "ts-2.3-04", "q": "After expanding the agent's MCP tools with delivery-specific capabilities [apply_promo_code, update_delivery_address, reconcile_delivery], the total tool count has grown from 1 to 7. We have observed that the agent now shows tool selection accuracy has dropped from 86% to 71%. Log analysis reveals the majority of errors involve the agent selecting between semantically overlapping tools — calling issue_credit when process_refund was correct, and calling check_delivery_status when looking order_allready_returns_the_needed_data. Which approach structurally eliminate the semantic overlap identified in the error source?", "o": {"A": "Consolidate semantically overlapping tools – merge issue_credit and process_refund into a single handle_promotions tool with an action parameter and fold check_delivery_status into lookup_order with an optional include_tracking flag.", "B": "Enable the tool search tool with defer_loading on the six new tools, keeping the original two always loaded, so the agent dynamically discovers specialized tools only when needed.", "C": "Add few-shot examples to the system prompt demonstrating correct selection for each ambiguous tool, such as showing when issue_credit applies versus when process_refund is appropriate.", "D": "Split the tools across two sub-agents — a 'financial resolution' agent with issue_credit, process_refund, return_order, and apply_promo_code and a 'delivery operations' agent with the remaining delivery tools — with a coordinating routing between them."}, "a": "A", "w": "", "c": "Tool Design", "dup": "", "conflict": false, "ts": "ts-2.3"}
];

