const CONCEPTS=[
  {id:"c-agentic-loop",ts:"ts-1.1",domain:"D1",level:"Foundation",title:"Agentic Loop Lifecycle",insight:"stop_reason is the ONLY reliable signal for agentic loop control"},
  {id:"c-tool-use-flow",ts:"ts-1.1",domain:"D1",level:"Foundation",title:"Tool Use Flow & Mechanics",insight:"Tool use follows a define → select → execute → return cycle"},
  {id:"c-coordinator-subagent",ts:"ts-1.2",domain:"D1",level:"Intermediate",title:"Coordinator-Subagent (Orchestrator) Pattern",insight:"All communication flows through the coordinator (hub-and-spoke)"},
  {id:"c-narrow-decomp-risk",ts:"ts-1.2",domain:"D1",level:"Intermediate",title:"Narrow Decomposition Risk",insight:"Narrow task decomposition causes incomplete results even when all subtasks succeed"},
  {id:"c-task-tool",ts:"ts-1.3",domain:"D1",level:"Intermediate",title:"Subagent Invocation & the Task Tool",insight:"The Task tool spawns subagents; allowedTools must include 'Task' for the coordinator"},
  {id:"c-agentdefinition",ts:"ts-1.3",domain:"D1",level:"Advanced",title:"AgentDefinition Configuration",insight:"AgentDefinition includes description, system prompt, and tool restrictions per subagent type"},
  {id:"c-workflow-enforcement",ts:"ts-1.4",domain:"D1",level:"Intermediate",title:"Multi-Step Workflow Enforcement",insight:"Programmatic prerequisites are more reliable than prompt-based ordering"},
  {id:"c-workflow-orchestration",ts:"ts-1.4",domain:"D1",level:"Advanced",title:"Multi-Step Workflow Orchestration",insight:"Decompose multi-concern requests and investigate in parallel"},
  {id:"c-posttooluse-hooks",ts:"ts-1.5",domain:"D1",level:"Intermediate",title:"Agent SDK Hooks: PostToolUse & Interception",insight:"PostToolUse hooks normalize tool output before the agent processes it"},
  {id:"c-decomp-routing",ts:"ts-1.6",domain:"D1",level:"Intermediate",title:"Task Decomposition & Routing Strategies",insight:"Use prompt chaining for predictable workflows, dynamic decomposition for open-ended tasks"},
  {id:"c-adaptive-vs-fixed",ts:"ts-1.6",domain:"D1",level:"Advanced",title:"Adaptive vs Fixed Decomposition",insight:"Fixed pipelines for predictable workflows; adaptive decomposition for exploration"},
  {id:"c-session-state",ts:"ts-1.7",domain:"D1",level:"Intermediate",title:"Session State & Resumption",insight:"Use --resume [session-name] to continue named investigation sessions"},
  {id:"c-tool-descriptions",ts:"ts-2.1",domain:"D2",level:"Foundation",title:"Tool Definitions & Descriptions",insight:"Tool descriptions are the #1 lever for tool selection accuracy"},
  {id:"c-tool-selection-debug",ts:"ts-2.1",domain:"D2",level:"Intermediate",title:"Tool Selection Reliability & Debugging",insight:"Diagnose tool selection issues: descriptions first, then system prompt, then examples"},
  {id:"c-structured-errors",ts:"ts-2.2",domain:"D2",level:"Intermediate",title:"Structured Error Response Design",insight:"Use the MCP isError flag to distinguish tool failures from successful empty results"},
  {id:"c-retry-patterns",ts:"ts-2.2",domain:"D2",level:"Advanced",title:"Error Recovery & Retry Patterns",insight:"Structured isRetryable metadata prevents wasted retry attempts on non-retryable errors"},
  {id:"c-least-privilege",ts:"ts-2.3",domain:"D2",level:"Intermediate",title:"Tool Distribution & Least Privilege",insight:"Each agent should have only the tools needed for its specific role (4-5 tools, not 18)"},
  {id:"c-mcp-scoping",ts:"ts-2.4",domain:"D2",level:"Intermediate",title:"MCP Server Configuration & Scoping",insight:"Use project-scoped .mcp.json for team tools, user-scoped ~/.claude.json for personal tools"},
  {id:"c-community-vs-custom",ts:"ts-2.4",domain:"D2",level:"Advanced",title:"Community vs Custom MCP Servers",insight:"Use community MCP servers for standard integrations; build custom only for team-specific needs"},
  {id:"c-builtin-tools",ts:"ts-2.5",domain:"D2",level:"Foundation",title:"Built-in Claude Code Tools",insight:"Grep searches file contents; Glob finds files by name pattern — don't confuse them"},
  {id:"c-claudemd-hierarchy",ts:"ts-3.1",domain:"D3",level:"Foundation",title:"CLAUDE.md Configuration Hierarchy",insight:"Project CLAUDE.md is loaded for every conversation; user-level has lowest priority"},
  {id:"c-claudemd-import",ts:"ts-3.1",domain:"D3",level:"Foundation",title:"Modular CLAUDE.md with @import",insight:"@import lets each package selectively include relevant standards files"},
  {id:"c-skills-commands",ts:"ts-3.2",domain:"D3",level:"Foundation",title:"Custom Skills & Slash Commands",insight:"Project skills/commands live in .claude/ (version-controlled, team-wide); personal ones in ~/.claude/"},
  {id:"c-skill-frontmatter",ts:"ts-3.2",domain:"D3",level:"Intermediate",title:"Skill Frontmatter Configuration",insight:"context: fork isolates skill execution from main conversation"},
  {id:"c-path-rules",ts:"ts-3.3",domain:"D3",level:"Foundation",title:"Path-Specific Rules (.claude/rules/)",insight:"Use .claude/rules/ with glob patterns for file-type-specific conventions"},
  {id:"c-plan-vs-direct",ts:"ts-3.4",domain:"D3",level:"Foundation",title:"Plan Mode vs Direct Execution",insight:"Use plan mode for ambiguous requirements with multiple valid approaches"},
  {id:"c-iterative-refinement",ts:"ts-3.5",domain:"D3",level:"Foundation",title:"Iterative Refinement Techniques",insight:"Concrete input/output examples beat prose descriptions for communicating transformations"},
  {id:"c-tdd-interview",ts:"ts-3.5",domain:"D3",level:"Advanced",title:"Test-Driven Iteration & Interview Pattern",insight:"Test failures are unambiguous feedback — more effective than prose review"},
  {id:"c-cicd-integration",ts:"ts-3.6",domain:"D3",level:"Foundation",title:"CI/CD Integration with Claude Code",insight:"Use -p (--print) flag for non-interactive CI/CD execution"},
  {id:"c-cicd-structured",ts:"ts-3.6",domain:"D3",level:"Advanced",title:"CI/CD Structured Output & Incremental Reviews",insight:"--output-format json with --json-schema enables automated inline PR comments"},
  {id:"c-explicit-criteria",ts:"ts-4.1",domain:"D4",level:"Foundation",title:"Explicit Criteria over Vague Instructions",insight:"Replace vague goals with specific, categorical criteria the model can apply deterministically"},
  {id:"c-prompt-specificity",ts:"ts-4.1",domain:"D4",level:"Foundation",title:"Prompt Specificity & Precision",insight:"Replace vague goals with specific, actionable criteria"},
  {id:"c-classification-consistency",ts:"ts-4.1",domain:"D4",level:"Intermediate",title:"Classification Consistency & False Positive Reduction",insight:"Use absolute criteria with concrete examples for each classification level"},
  {id:"c-fewshot",ts:"ts-4.2",domain:"D4",level:"Foundation",title:"Few-Shot Prompting Techniques",insight:"Few-shot examples are more reliable than instructions for consistent formatting"},
  {id:"c-io-examples",ts:"ts-4.2",domain:"D4",level:"Foundation",title:"Concrete Input-Output Examples",insight:"Concrete examples eliminate ambiguity that prose descriptions create"},
  {id:"c-structured-output",ts:"ts-4.3",domain:"D4",level:"Intermediate",title:"Structured Output via Tool Use & JSON Schemas",insight:"Tool use with JSON schemas eliminates syntax errors but not semantic errors"},
  {id:"c-tool-choice",ts:"ts-4.3",domain:"D4",level:"Intermediate",title:"tool_choice Options & Forced Tool Selection",insight:"tool_choice 'auto' may return text; 'any' guarantees a tool call; forced selection guarantees a specific tool"},
  {id:"c-retry-feedback",ts:"ts-4.4",domain:"D4",level:"Intermediate",title:"Retry-with-Error-Feedback Pattern",insight:"Append specific validation errors to the retry prompt — not just 'try again'"},
  {id:"c-dismissal-analysis",ts:"ts-4.4",domain:"D4",level:"Advanced",title:"Feedback Loop Design & Dismissal Pattern Analysis",insight:"Add detected_pattern fields to enable systematic analysis of false positive patterns"},
  {id:"c-batch-selection",ts:"ts-4.5",domain:"D4",level:"Intermediate",title:"Batch Processing Strategy & API Selection",insight:"Batch API saves 50% but has up to 24-hour processing with no latency SLA"},
  {id:"c-batch-failure",ts:"ts-4.5",domain:"D4",level:"Intermediate",title:"Batch Failure Handling & Constraints",insight:"Resubmit only failed documents identified by custom_id, not the entire batch"},
  {id:"c-batch-cost",ts:"ts-4.5",domain:"D4",level:"Advanced",title:"Batch Cost Optimization Strategies",insight:"50% batch savings are reduced by resubmission costs — maximize first-pass success"},
  {id:"c-self-critique",ts:"ts-4.6",domain:"D4",level:"Intermediate",title:"Self-Critique Limitations & Independent Review",insight:"Self-review in the same context suffers from confirmation bias — the model retains generation reasoning"},
  {id:"c-multipass-review",ts:"ts-4.6",domain:"D4",level:"Advanced",title:"Multi-Pass Review Architecture",insight:"Split large reviews into per-file local passes plus cross-file integration passes"},
  {id:"c-context-windows",ts:"ts-5.1",domain:"D5",level:"Foundation",title:"Context Windows & Provision Strategies",insight:"Context window = input tokens + output tokens combined"},
  {id:"c-lost-in-middle",ts:"ts-5.1",domain:"D5",level:"Intermediate",title:"Lost in the Middle & Position Effects",insight:"Models attend best to beginning and end of context, less to the middle"},
  {id:"c-progressive-summary",ts:"ts-5.1",domain:"D5",level:"Intermediate",title:"Progressive Summarization Risks",insight:"Extract critical transactional facts into a persistent block outside summarized history"},
  {id:"c-token-caching",ts:"ts-5.1",domain:"D5",level:"Advanced",title:"Context Token Management & Caching",insight:"Trim verbose tool outputs to only relevant fields before they accumulate in context"},
  {id:"c-escalation-criteria",ts:"ts-5.2",domain:"D5",level:"Intermediate",title:"Escalation Criteria & Patterns",insight:"Escalate for genuine policy gaps, not just complexity"},
  {id:"c-escalation-triggers",ts:"ts-5.2",domain:"D5",level:"Intermediate",title:"Appropriate Escalation Triggers",insight:"Distinguish genuine policy gaps from mere complexity when deciding to escalate"},
  {id:"c-ambiguous-results",ts:"ts-5.2",domain:"D5",level:"Foundation",title:"Ambiguous Result Handling",insight:"Ask for clarification on ambiguous results rather than guessing"},
  {id:"c-error-propagation",ts:"ts-5.3",domain:"D5",level:"Intermediate",title:"Error Propagation in Multi-Agent Systems",insight:"Handle errors at the lowest level capable of resolving them"},
  {id:"c-graceful-degradation",ts:"ts-5.3",domain:"D5",level:"Intermediate",title:"Graceful Degradation with Transparency",insight:"Continue operating with partial data but annotate gaps transparently"},
  {id:"c-context-budget",ts:"ts-5.4",domain:"D5",level:"Intermediate",title:"Context Budget Management & Upstream Reduction",insight:"Reduce data volume at the source rather than trying to handle large inputs downstream"},
  {id:"c-codebase-exploration",ts:"ts-5.4",domain:"D5",level:"Intermediate",title:"Codebase Exploration Context Strategies",insight:"Use scratchpad files to externalize findings beyond the context window"},
  {id:"c-human-review",ts:"ts-5.5",domain:"D5",level:"Intermediate",title:"Human Review Workflow Design",insight:"Aggregate accuracy metrics can mask poor performance on specific segments"},
  {id:"c-confidence-calibration",ts:"ts-5.5",domain:"D5",level:"Advanced",title:"Confidence Calibration & Review Thresholds",insight:"Calibrate confidence thresholds using labeled validation sets, not intuition"},
  {id:"c-conflicting-sources",ts:"ts-5.6",domain:"D5",level:"Intermediate",title:"Handling Conflicting Data Sources",insight:"Preserve conflicting data with source attribution; don't choose one"},
  {id:"c-provenance",ts:"ts-5.6",domain:"D5",level:"Intermediate",title:"Information Provenance & Claim-Source Mappings",insight:"Require structured claim-source mappings from subagents to preserve attribution"},
];

